===== JSONL 1544 | learning_management_system_lms_1 | 3 =====
TASK: In my course 'Fundamentals of Project Management', submit Quiz 2 with the following answers in order: ['B', 'D', 'A', 'C', 'C', 'B', 'A', 'D', 'B', 'C'] and return my score.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Expected answers in order for Quiz 2
    expected_answers = ['B', 'D', 'A', 'C', 'C', 'B', 'A', 'D', 'B', 'C']

    # Quiz 2 has quiz_id = 2 (from the database dump)
    quiz_id = 2
    user_id = 1  # learner_one is the primary user

    # Check initial state - should have no submission for quiz 2
    initial_submissions = safe_query(
        initial_db_path,
        "SELECT id FROM user_quiz_submissions WHERE user_id = ? AND quiz_id = ?",
        (user_id, quiz_id)
    )

    # Check final state - should have a submission for quiz 2
    final_submissions = safe_query(
        final_db_path,
        "SELECT id, total_score, max_score FROM user_quiz_submissions WHERE user_id = ? AND quiz_id = ?",
        (user_id, quiz_id)
    )

    # Verify a new submission was created
    if len(final_submissions) <= len(initial_submissions):
        return {"result": "others"}

    # Get the latest submission ID
    submission_id = final_submissions[-1][0]
    total_score = final_submissions[-1][1]
    max_score = final_submissions[-1][2]

    # Verify score exists and is not None
    if total_score is None:
        return {"result": "others"}

    # Get all answers for this submission
    answers = safe_query(
        final_db_path,
        """SELECT qq.question_number, uqa.selected_option 
           FROM user_quiz_answers uqa
           JOIN quiz_questions qq ON uqa.question_id = qq.id
           WHERE uqa.submission_id = ?
           ORDER BY qq.question_number""",
        (submission_id,)
    )

    # Verify exactly 10 answers were submitted
    if len(answers) != 10:
        return {"result": "others"}

    # Verify the answers match the expected answers in order
    for i, (question_num, selected_option) in enumerate(answers):
        if question_num != i + 1:  # Verify question numbers are 1-10 in order
            return {"result": "others"}
        if selected_option != expected_answers[i]:
            return {"result": "others"}

    # Verify final_answer contains score information
    if not final_answer:
        return {"result": "others"}

    # Look for score in final_answer - should contain a number that matches the total_score
    # Common patterns: "score: 8", "8/10", "8.0", "scored 8", etc.
    score_patterns = [
        r"score[:\s]+([\d.]+)",
        r"([\d.]+)\s*/\s*10",
        r"([\d.]+)\s*out\s*of\s*10",
        r"scored\s+([\d.]+)",
        r"result[:\s]+([\d.]+)",
        r"\b([\d.]+)\s*points?\b"
    ]

    score_found = False
    for pattern in score_patterns:
        match = re.search(pattern, final_answer, re.IGNORECASE)
        if match:
            try:
                reported_score = float(match.group(1))
                # Allow for small floating point differences
                if abs(reported_score - total_score) < 0.01:
                    score_found = True
                    break
            except (ValueError, IndexError):
                continue

    if not score_found:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
===== JSONL 9961 | enterprise_admin_portal_1 | 1 =====
TASK: List all menus and their menu_items available for the 'Downtown HQ' location on 2025-01-15, and return only the items that are tagged as both 'gluten_free' and 'high_protein' with fewer than 700 calories.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    if not final_answer or len(final_answer.strip()) == 0:
        return {"result": "others"}

    final_answer_lower = final_answer.lower()

    # Step 1: Get location_id for Downtown HQ
    location_query = """
        SELECT id FROM locations 
        WHERE name = 'Downtown HQ'
    """
    location_results = safe_query(final_db_path, location_query)
    if not location_results:
        return {"result": "others"}
    location_id = location_results[0][0]

    # Step 2: Get provider_locations for Downtown HQ
    provider_location_query = """
        SELECT id FROM provider_locations
        WHERE location_id = ?
    """
    provider_locations = safe_query(final_db_path, provider_location_query, (location_id,))
    if not provider_locations:
        return {"result": "others"}

    provider_location_ids = [pl[0] for pl in provider_locations]

    # Step 3: Get menus for these provider_locations that cover 2025-01-15
    menu_query = """
        SELECT id FROM menus
        WHERE provider_location_id IN ({}) 
        AND date('2025-01-15') BETWEEN date(start_date) AND date(end_date)
    """.format(','.join('?' * len(provider_location_ids)))

    menu_results = safe_query(final_db_path, menu_query, tuple(provider_location_ids))
    if not menu_results:
        return {"result": "others"}

    menu_ids = [m[0] for m in menu_results]

    # Step 4: Get menu_items for these menus that have calories < 700
    menu_items_query = """
        SELECT mi.id, mi.name, mi.calories
        FROM menu_items mi
        WHERE mi.menu_id IN ({}) AND mi.calories < 700
    """.format(','.join('?' * len(menu_ids)))

    menu_items = safe_query(final_db_path, menu_items_query, tuple(menu_ids))
    if not menu_items:
        return {"result": "others"}

    # Step 5: Filter menu_items that have BOTH gluten_free AND high_protein tags
    valid_items = []
    for item_id, item_name, calories in menu_items:
        tags_query = """
            SELECT tag FROM menu_item_tags
            WHERE menu_item_id = ?
        """
        tags = safe_query(final_db_path, tags_query, (item_id,))
        tag_set = set(tag[0] for tag in tags)

        if 'gluten_free' in tag_set and 'high_protein' in tag_set:
            valid_items.append((item_id, item_name, calories))

    if not valid_items:
        return {"result": "others"}

    # Step 6: Check if final_answer mentions at least one of the valid items
    found_match = False
    for item_id, item_name, calories in valid_items:
        item_name_normalized = item_name.lower().strip()
        if item_name_normalized in final_answer_lower:
            found_match = True
            break

        item_id_str = str(item_id)
        if item_id_str in final_answer:
            found_match = True
            break

    if not found_match:
        return {"result": "others"}

    # Step 7: Verify final_answer mentions key contextual elements
    has_menu_context = ('menu' in final_answer_lower)
    has_location_context = ('downtown' in final_answer_lower or 'hq' in final_answer_lower)
    has_date_context = ('2025' in final_answer or '01-15' in final_answer or 'january' in final_answer_lower)
    has_tag_context = (
        ('gluten' in final_answer_lower and 'protein' in final_answer_lower) or
        ('gluten_free' in final_answer_lower or 'high_protein' in final_answer_lower)
    )
    has_calorie_context = ('calorie' in final_answer_lower or '700' in final_answer)

    if not has_menu_context:
        return {"result": "others"}

    # Step 8: Strong verification - at least 2 contextual matches beyond menu
    context_count = sum([
        has_location_context,
        has_date_context,
        has_tag_context,
        has_calorie_context
    ])

    if context_count < 2:
        return {"result": "others"}

    return {"result": "complete"}

