            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Verify property 6 is Sunset Ridge Apartments in Denver, CO
    property_check = safe_query(final_db_path, 
        "SELECT id, name, city, state FROM properties WHERE id = ?", (6,))
    if not property_check:
        return {"result": "others"}

