    if prop_name != "Sunset Ridge Apartments" or prop_city != "Denver" or prop_state != "CO":
        return {"result": "others"}

    # Step 2: Verify user 1 has property 6 in favorites
    favorite_check = safe_query(final_db_path,
        "SELECT id FROM favorites WHERE user_id = ? AND property_id = ?", (1, 6))
    if not favorite_check:
        return {"result": "others"}

    # Step 3: Get initial tours for comparison
    initial_tours = safe_query(initial_db_path,
        "SELECT id, user_id, property_id, tour_type, tour_datetime, time_zone, status, notes FROM tours")
    initial_tour_ids = set(tour[0] for tour in initial_tours)

    # Step 4: Get final tours and find new ones
    final_tours = safe_query(final_db_path,
        "SELECT id, user_id, property_id, tour_type, tour_datetime, time_zone, status, notes FROM tours")

    new_tours = [tour for tour in final_tours if tour[0] not in initial_tour_ids]

    if not new_tours:
        return {"result": "others"}

    # Step 5: Check if any new tour matches all requirements
    for tour in new_tours:
        tour_id, user_id, property_id, tour_type, tour_datetime, time_zone, status, notes = tour

        # Check user_id is 1
        if user_id != 1:
            continue

        # Check property_id is 6
        if property_id != 6:
            continue

        # Check tour_type is in_person
        if tour_type != "in_person":
            continue

        # Check tour_datetime matches 2025-02-15 10:30
        # Accept various formats: 2025-02-15 10:30:00, 2025-02-15T10:30:00, etc.
        datetime_pattern = r"2025-02-15[\s T]10:30(?::00)?"
        if not re.search(datetime_pattern, tour_datetime):
            continue

        # Check time_zone is America/Denver (Mountain Time)
        if time_zone != "America/Denver":
            continue

        # Check status is scheduled
        if status != "scheduled":
            continue

        # Check notes contain the required text
        if not notes:
            continue

        # The note must mention 12-month lease and flexible move-in March 1-15
        required_phrases = [
            r"12[- ]month\s+lease",
            r"flexible\s+move[- ]in",
            r"March\s+1[- ]15"
        ]

        all_phrases_found = all(
            re.search(phrase, notes, re.IGNORECASE) for phrase in required_phrases
