import json
import sqlite3
import signal
import traceback
from pathlib import Path
import pyarrow.parquet as pq

ROOT = Path('/workspace/data/AgentWorldModel-1K')
OUT = Path('/tmp/awm-analysis-FY8vek')
DBDIR = OUT / 'initial_dbs'
DBDIR.mkdir(exist_ok=True)

class Timeout(Exception):
    pass

def alarm_handler(signum, frame):
    raise Timeout()

signal.signal(signal.SIGALRM, alarm_handler)

db_rows = {r['scenario']: r for r in map(json.loads, (ROOT / 'gen_db.jsonl').open())}
sample_rows = {r['scenario']: r for r in map(json.loads, (ROOT / 'gen_sample.jsonl').open())}
verifier_rows = list(map(json.loads, (ROOT / 'gen_verifier.pure_code.jsonl').open()))
verifier_map = {}
for i, row in enumerate(verifier_rows):
    verifier_map.setdefault((row['scenario'], row['task_idx']), []).append((i, row))
test_rows = pq.read_table(ROOT / 'verl/test.parquet').to_pylist()

def make_initial_db(scenario):
    path = DBDIR / f'{scenario}.db'
    if path.exists():
        return path
    conn = sqlite3.connect(path)
    cur = conn.cursor()
    schema_errors = []
    for table in db_rows[scenario]['db_schema'].get('tables', []):
        try:
            cur.execute(table['ddl'])
            for sql in table.get('indexes', []):
                cur.execute(sql)
            for sql in table.get('examples', []):
                cur.execute(sql)
        except Exception as exc:
            schema_errors.append(f"{table.get('name')}: {exc}")
    conn.commit()
    cur.execute('PRAGMA foreign_keys = ON;')
    insert_errors = []
    success = 0
    total = 0
    for table in sample_rows[scenario]['sample_data'].get('tables', []):
        for sql in table.get('insert_statements', []):
            total += 1
            try:
                cur.execute(sql)
                success += 1
            except sqlite3.Error as exc:
                insert_errors.append(f"{table.get('table_name')}: {exc}")
    conn.commit()
    conn.close()
    return path, {'schema_errors': schema_errors, 'insert_success': success,
                  'insert_total': total, 'insert_errors': insert_errors}

results = []
for test_idx, test_row in enumerate(test_rows):
    env = test_row['env_kwargs']
    key = (env['scenario'], env['task_idx'])
    db_path, db_info = make_initial_db(env['scenario'])
    answers = [
        ('none', None),
        ('empty', ''),
        ('generic', 'I have completed the requested task and verified all of the requested details. Here are the complete results for your request.'),
        ('task_restatement', env['task']),
    ]
    for rule_idx, rule in verifier_map[key]:
        namespace = {'__name__': f'awm_rule_{rule_idx}'}
        try:
            exec(compile(rule['verification']['code'], f'<rule-{rule_idx}>', 'exec'), namespace)
            fn = namespace['verify_task_completion']
        except Exception as exc:
            results.append({'test_idx': test_idx, 'rule_idx': rule_idx, 'scenario': key[0], 'task_idx': key[1],
                            'load_error': repr(exc), 'db_info': db_info})
            continue
        for answer_name, answer in answers:
            record = {'test_idx': test_idx, 'rule_idx': rule_idx, 'scenario': key[0], 'task_idx': key[1],
                      'answer': answer_name, 'task': env['task'], 'db_info': db_info}
            try:
                signal.alarm(5)
                verdict = fn(str(db_path), str(db_path), answer)
                signal.alarm(0)
                record['verdict'] = verdict
            except Exception as exc:
                signal.alarm(0)
                record['error'] = repr(exc)
                record['traceback'] = traceback.format_exc()
            results.append(record)
    if test_idx % 16 == 0:
        print('checked', test_idx, key, flush=True)

(OUT / 'noop_results.json').write_text(json.dumps(results, indent=2, default=str) + '\n')
print('wrote', len(results), 'results')
for r in results:
    verdict = r.get('verdict')
    complete = isinstance(verdict, dict) and verdict.get('result') == 'complete'
    if complete or 'error' in r or 'load_error' in r:
        print(r['test_idx'], r['rule_idx'], r['scenario'], r['task_idx'], r.get('answer'),
              'COMPLETE' if complete else r.get('error', r.get('load_error')), verdict)

