TASK: Create three new product catalog entries for my company: (1) item_code 'VALVE-1001', name 'Stainless Steel Ball Valve 1"', category 'Valves', specs 'PN16, 316SS, threaded', price_range '€18-€25'; (2) item_code 'VALVE-1002', name 'Stainless Steel Ball Valve 2"', category 'Valves', specs 'PN16, 316SS, flanged', price_range '€45-€60'; (3) item_code 'FITT-0501', name 'Elbow Fitting 1" 90°', category 'Fittings', specs 'brass, BSPT', price_range '€3-€5'.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Determine company_id for the buyer (user 1 is associated with company 1)
    company_id = 1

    # Get initial product catalog items for company 1
    initial_items = safe_query(
        initial_db_path,
        "SELECT item_code, name, category, specs, price_range FROM product_catalog_items WHERE company_id = ?",
        (company_id,)
    )

    # Get final product catalog items for company 1
    final_items = safe_query(
        final_db_path,
        "SELECT item_code, name, category, specs, price_range FROM product_catalog_items WHERE company_id = ?",
        (company_id,)
    )

    # Check if exactly 3 new items were added
    if len(final_items) != len(initial_items) + 3:
        return {"result": "others"}

    # Convert to sets for comparison
    initial_set = set(initial_items)
    final_set = set(final_items)
    new_items = final_set - initial_set

    # Verify exactly 3 new items
    if len(new_items) != 3:
        return {"result": "others"}

    # Define expected products with exact specifications
    expected_products = {
        'VALVE-1001': {
            'name': 'Stainless Steel Ball Valve 1"',
            'category': 'Valves',
            'specs': 'PN16, 316SS, threaded',
            'price_range': '€18-€25'
        },
        'VALVE-1002': {
            'name': 'Stainless Steel Ball Valve 2"',
            'category': 'Valves',
            'specs': 'PN16, 316SS, flanged',
            'price_range': '€45-€60'
        },
        'FITT-0501': {
            'name': 'Elbow Fitting 1" 90°',
            'category': 'Fittings',
            'specs': 'brass, BSPT',
            'price_range': '€3-€5'
        }
    }

    # Convert new_items to a dictionary keyed by item_code
    new_items_dict = {}
    for item in new_items:
        item_code, name, category, specs, price_range = item
        new_items_dict[item_code] = {
            'name': name,
            'category': category,
            'specs': specs,
            'price_range': price_range
        }

    # Verify all three expected products exist with exact specifications
    for expected_code, expected_data in expected_products.items():
        if expected_code not in new_items_dict:
            return {"result": "others"}

        actual_data = new_items_dict[expected_code]

        # Check each field matches exactly
        if actual_data['name'] != expected_data['name']:
            return {"result": "others"}
        if actual_data['category'] != expected_data['category']:
            return {"result": "others"}
        if actual_data['specs'] != expected_data['specs']:
            return {"result": "others"}
        if actual_data['price_range'] != expected_data['price_range']:
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
