TASK: Schedule a COVID-19 booster vaccination appointment for myself at my default CVS store location for the earliest available date after 6:00 PM on a weekday.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get initial vaccine appointments for user_id=1 with COVID-19 booster at store 1
    initial_appointments = safe_query(
        initial_db_path,
        "SELECT id, appointment_datetime, status FROM vaccine_appointments WHERE user_id = ? AND vaccine_type_id = ? AND store_id = ?",
        (1, 1, 1)
    )

    # Get final vaccine appointments for user_id=1 with COVID-19 booster at store 1
    final_appointments = safe_query(
        final_db_path,
        "SELECT id, appointment_datetime, status, family_member_id FROM vaccine_appointments WHERE user_id = ? AND vaccine_type_id = ? AND store_id = ?",
        (1, 1, 1)
    )

    # Check if exactly one new appointment was added
    if len(final_appointments) != len(initial_appointments) + 1:
        return {"result": "others"}

    # Find the new appointment (id not in initial set)
    initial_ids = {row[0] for row in initial_appointments}
    new_appointments = [row for row in final_appointments if row[0] not in initial_ids]

    if len(new_appointments) != 1:
        return {"result": "others"}

    new_appt = new_appointments[0]
    appt_id, appt_datetime_str, appt_status, family_member_id = new_appt

    # Verify status is 'scheduled'
    if appt_status != 'scheduled':
        return {"result": "others"}

    # Verify it's for the user themselves (not a family member)
    if family_member_id is not None:
        return {"result": "others"}

    # Parse appointment datetime
    try:
        appt_dt = datetime.strptime(appt_datetime_str, '%Y-%m-%d %H:%M:%S')
    except Exception:
        return {"result": "others"}

    # Verify it's a weekday (Monday=0, Sunday=6)
    if appt_dt.weekday() >= 5:  # Saturday or Sunday
        return {"result": "others"}

    # Verify time is after 6:00 PM (18:00)
    if appt_dt.hour < 18:
        return {"result": "others"}

    # Verify appointment is in the future
    # The latest timestamp in initial DB is 2025-12-31 12:37:29
    # So appointment should be after this time
    try:
        reference_time = datetime(2025, 12, 31, 12, 37, 29)
        if appt_dt <= reference_time:
            return {"result": "others"}
    except Exception:
        pass  # If we can't verify this, continue with other checks

    # All checks passed
    return {"result": "complete"}
