TASK: Create a new active vehicle record in my primary fleet with VIN '1FTYR10C2TPA12345', license plate 'ABC-7392', make 'Ford', model 'Transit 250', capacity '3,000 kg', current odometer 128450 km, and status 'active'.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if the vehicle with the specified VIN exists in the final database
    vin = '1FTYR10C2TPA12345'
    license_plate = 'ABC-7392'

    # Query initial database to confirm vehicle doesn't exist there
    initial_vehicle = safe_query(
        initial_db_path,
        "SELECT * FROM vehicles WHERE vin = ? OR license_plate = ?",
        (vin, license_plate)
    )

    # Query final database to get the new vehicle
    final_vehicle = safe_query(
        final_db_path,
        "SELECT id, fleet_id, vin, license_plate, make, model, capacity, vehicle_type, status, current_odometer_km FROM vehicles WHERE vin = ?",
        (vin,)
    )

    # If vehicle doesn't exist in final database, task not complete
    if not final_vehicle:
        return {"result": "others"}

    # If vehicle already existed in initial database, it's not a new creation
    if initial_vehicle:
        return {"result": "others"}

    # Extract the vehicle data
    vehicle = final_vehicle[0]
    v_id, v_fleet_id, v_vin, v_license_plate, v_make, v_model, v_capacity, v_vehicle_type, v_status, v_odometer = vehicle

    # Verify all required fields match exactly
    # Check VIN
    if v_vin != vin:
        return {"result": "others"}

    # Check license plate
    if v_license_plate != license_plate:
        return {"result": "others"}

    # Check make (case-insensitive)
    if not v_make or v_make.lower() != 'ford':
        return {"result": "others"}

    # Check model (case-insensitive, allow slight variations)
    if not v_model or v_model.lower().replace(' ', '') != 'transit250':
        return {"result": "others"}

    # Check capacity - normalize formatting (remove spaces, handle variations)
    if v_capacity:
        normalized_capacity = v_capacity.replace(' ', '').replace(',', '').lower()
        if normalized_capacity not in ['3000kg', '3,000kg']:
            return {"result": "others"}
    else:
        return {"result": "others"}

    # Check status
    if v_status != 'active':
        return {"result": "others"}

    # Check odometer
    if v_odometer is None or abs(v_odometer - 128450.0) > 0.01:
        return {"result": "others"}

    # Check fleet_id - should be 10 (Primary Logistics Fleet)
    # Query to confirm fleet_id 10 is the Primary Logistics Fleet
    fleet_info = safe_query(
        final_db_path,
        "SELECT id, name FROM fleets WHERE id = ?",
        (10,)
    )

    if not fleet_info or fleet_info[0][1] != 'Primary Logistics Fleet':
        return {"result": "others"}

    if v_fleet_id != 10:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
