TASK: Create a new fare product named 'Weekend Saver' for route 'City C – Beachside' that applies only on Saturdays and Sundays, offers a 25% discount on standard class for adults, is nonrefundable, and set the base price to 18.50 USD for the full route distance.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if 'Weekend Saver' fare product exists in initial database
    initial_weekend_saver = safe_query(
        initial_db_path,
        "SELECT id, name, discount_percent, class, passenger_type, refundable, base_price, currency, applicable_days FROM fare_products WHERE name = ?",
        ('Weekend Saver',)
    )

    # Check if 'Weekend Saver' fare product exists in final database
    final_weekend_saver = safe_query(
        final_db_path,
        "SELECT id, name, discount_percent, class, passenger_type, refundable, base_price, currency, applicable_days FROM fare_products WHERE name = ?",
        ('Weekend Saver',)
    )

    # If Weekend Saver doesn't exist in final DB, task not complete
    if not final_weekend_saver:
        return {"result": "others"}

    # Get the fare product details
    fare_id, name, discount_percent, fare_class, passenger_type, refundable, base_price, currency, applicable_days = final_weekend_saver[0]

    # Verify all attributes match the requirements
    # 1. Name should be 'Weekend Saver'
    if name != 'Weekend Saver':
        return {"result": "others"}

    # 2. Discount should be 25%
    if discount_percent != 25.0:
        return {"result": "others"}

    # 3. Class should be 'standard'
    if fare_class != 'standard':
        return {"result": "others"}

    # 4. Passenger type should be 'adult'
    if passenger_type != 'adult':
        return {"result": "others"}

    # 5. Should be nonrefundable (refundable=0)
    if refundable != 0:
        return {"result": "others"}

    # 6. Base price should be 18.50
    if abs(base_price - 18.5) > 0.01:
        return {"result": "others"}

    # 7. Currency should be USD
    if currency != 'USD':
        return {"result": "others"}

    # 8. Applicable days should include Saturday and Sunday
    if not applicable_days:
        return {"result": "others"}

    # Check for various weekend formats: SAT,SUN or SATURDAY,SUNDAY or similar
    applicable_days_upper = applicable_days.upper()
    has_saturday = 'SAT' in applicable_days_upper or 'SATURDAY' in applicable_days_upper
    has_sunday = 'SUN' in applicable_days_upper or 'SUNDAY' in applicable_days_upper

    if not (has_saturday and has_sunday):
        return {"result": "others"}

    # Check if this should only apply to weekends (not weekdays)
    # Verify it doesn't include weekdays
    weekdays = ['MON', 'TUE', 'WED', 'THU', 'FRI', 'MONDAY', 'TUESDAY', 'WEDNESDAY', 'THURSDAY', 'FRIDAY']
    for weekday in weekdays:
        if weekday in applicable_days_upper:
            return {"result": "others"}

    # 9. Check route association with 'City C – Beachside' (route_id=6)
    route_id = safe_query(
        final_db_path,
        "SELECT id FROM routes WHERE name = ?",
        ('City C – Beachside',)
    )

    if not route_id:
        return {"result": "others"}

    route_id = route_id[0][0]

    # Check if the fare product is linked to the route in route_fare_products
    route_fare_link = safe_query(
        final_db_path,
        "SELECT route_id, fare_product_id, full_route_only FROM route_fare_products WHERE route_id = ? AND fare_product_id = ?",
        (route_id, fare_id)
    )

    if not route_fare_link:
        return {"result": "others"}

    # 10. Verify full_route_only is set to 1
    _, _, full_route_only = route_fare_link[0]
    if full_route_only != 1:
        return {"result": "others"}

    # Verify this is a NEW fare product (should have more fare products in final than initial)
    initial_count = len(safe_query(initial_db_path, "SELECT id FROM fare_products", ()))
    final_count = len(safe_query(final_db_path, "SELECT id FROM fare_products", ()))

    if final_count <= initial_count:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

