TABLE analysis_tasks 
INSERT INTO analysis_tasks (id, task_id, subject, method, assumptions, overall_explanation, created_at, updated_at) VALUES (1, 2, '2023 Monthly Sales Drivers', 'Correlation and simple linear regression on monthly aggregates.', 'Assumes relationships between predictors and revenue are approximately linear at monthly granularity and that no major external shocks occurred beyond noted campaigns.', 'We explored how website traffic, email signups, and average order value relate to monthly revenue. By inspecting correlations and simple regressions, we found that average order value is the strongest direct driver, followed by website traffic and then email signups. Seasonality around November–December interacts with all three, but the ranking of predictors remains stable. This helps prioritize Q1 2024 levers that are both controllable and high-impact.', '2023-12-02 09:50:00', '2023-12-02 10:00:00');

