TABLE analysis_recommendations 
INSERT INTO analysis_recommendations (id, analysis_id, category, recommendation_text, expected_impact, priority, period, created_at) VALUES (1, 1, 'Pricing & Packaging', 'Run A/B tests to nudge average order value up 5–10% by bundling best-selling products and offering small add-ons at checkout.', 'High impact on revenue with limited operational risk.', 'High', 'Q1 2024', '2023-12-02 09:55:00');
INSERT INTO analysis_recommendations (id, analysis_id, category, recommendation_text, expected_impact, priority, period, created_at) VALUES (2, 1, 'Growth Marketing', 'Invest in paid campaigns that historically bring high-intent traffic, targeting a 15% lift in qualified site sessions.', 'Medium to high revenue impact depending on acquisition cost.', 'High', 'Jan–Mar 2024', '2023-12-02 09:55:10');
INSERT INTO analysis_recommendations (id, analysis_id, category, recommendation_text, expected_impact, priority, period, created_at) VALUES (3, 1, 'Lifecycle & Email', 'Introduce a structured welcome series and cart-abandon flows to turn new email signups into first-time purchasers.', 'Medium impact, compounding over time via repeat buyers.', 'Medium', 'Q1 2024', '2023-12-02 09:55:20');
INSERT INTO analysis_recommendations (id, analysis_id, category, recommendation_text, expected_impact, priority, period, created_at) VALUES (4, 1, 'Discount Policy', 'Tighten blanket discounts and shift to targeted offers for price-sensitive segments to avoid eroding margin.', 'Protects margin while maintaining conversion on key segments.', 'Medium', 'Q1 2024', '2023-12-02 09:55:30');

