######## RULE 118 productivity_assistant_1 1
TASK: Analyze the uploaded CSV file of monthly sales data for 2023, identify the three strongest predictors of revenue using simple regression-style reasoning, and produce a plain-English explanation plus a table of recommended actions for Q1 2024.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            conn.row_factory = sqlite3.Row
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Find the sales_analysis task for 2023
    tasks = safe_query(final_db_path, 
        "SELECT id, task_type, status FROM tasks WHERE task_type = 'sales_analysis' AND status = 'completed'"
    )

    if not tasks:
        return {"result": "others"}

    # Get the task_id (should be 2 based on the dump)
    task_id = None
    for task in tasks:
        # Check if this is the 2023 sales analysis
        task_id = task['id']
        break

    if not task_id:
        return {"result": "others"}

    # Check if analysis_tasks record exists with meaningful explanation
    analysis_tasks = safe_query(final_db_path,
        "SELECT id, overall_explanation FROM analysis_tasks WHERE task_id = ?",
        (task_id,)
    )

    if not analysis_tasks:
        return {"result": "others"}

    analysis_task = analysis_tasks[0]
    analysis_id = analysis_task['id']
    overall_explanation = analysis_task['overall_explanation']

    # Verify explanation exists and has meaningful content (at least 50 chars)
    if not overall_explanation or len(overall_explanation.strip()) < 50:
        return {"result": "others"}

    # Check for exactly 3 top predictors with ranks 1, 2, 3
    predictors = safe_query(final_db_path,
        "SELECT importance_rank, variable_name, description, correlation_coefficient FROM analysis_predictors WHERE analysis_id = ? AND importance_rank <= 3 ORDER BY importance_rank",
        (analysis_id,)
    )

    if len(predictors) != 3:
        return {"result": "others"}

    # Verify the predictors have ranks 1, 2, 3
    expected_ranks = {1, 2, 3}
    actual_ranks = {p['importance_rank'] for p in predictors}
    if actual_ranks != expected_ranks:
        return {"result": "others"}

    # Verify each predictor has required fields
    for predictor in predictors:
        if not predictor['variable_name'] or len(predictor['variable_name'].strip()) == 0:
            return {"result": "others"}
        if not predictor['description'] or len(predictor['description'].strip()) < 10:
            return {"result": "others"}
        if predictor['correlation_coefficient'] is None:
            return {"result": "others"}

    # Check for Q1 2024 recommendations
    recommendations = safe_query(final_db_path,
        "SELECT recommendation_text, period FROM analysis_recommendations WHERE analysis_id = ?",
        (analysis_id,)
    )

    if not recommendations:
        return {"result": "others"}

    # Verify at least one recommendation mentions Q1 2024
    q1_2024_found = False
    for rec in recommendations:
        period = rec['period'] or ''
        recommendation_text = rec['recommendation_text'] or ''

        # Check if period mentions Q1 2024 or similar variations
        if re.search(r'Q1\s*2024|2024\s*Q1|Jan.*2024|February.*2024|March.*2024|first quarter.*2024', period, re.IGNORECASE):
            q1_2024_found = True

        # Verify recommendation has meaningful content
        if len(recommendation_text.strip()) < 20:
            return {"result": "others"}

    if not q1_2024_found:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}


######## RULE 609 booking_reservations_24 7
TASK: Set up an email and SMS reminder workflow for my 'Webinar Q&A' event type to send a reminder 24 hours before, 1 hour before, and 10 minutes before the event start time with customized messages for each reminder.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Find the Webinar Q&A event type ID
    event_type_query = "SELECT id FROM event_types WHERE name = 'Webinar Q&A'"
    event_types = safe_query(final_db_path, event_type_query)

    if not event_types:
        return {"result": "others"}

    event_type_id = event_types[0][0]

    # Required time offsets in minutes
    required_offsets = [1440, 60, 10]  # 24 hours, 1 hour, 10 minutes
    required_channels = ['email', 'sms']

    # Query all reminders for the Webinar Q&A event type
    reminders_query = """
        SELECT channel, offset_minutes_before_start, message 
        FROM event_type_reminders 
        WHERE event_type_id = ?
        ORDER BY offset_minutes_before_start DESC, channel
    """
    reminders = safe_query(final_db_path, reminders_query, (event_type_id,))

    if not reminders:
        return {"result": "others"}

    # Check if we have exactly 6 reminders (3 time offsets × 2 channels)
    if len(reminders) != 6:
        return {"result": "others"}

    # Verify all required combinations exist
    found_combinations = set()
    messages = []

    for channel, offset, message in reminders:
        # Check message is not empty and has customized content
        if not message or len(message.strip()) == 0:
            return {"result": "others"}

        messages.append(message.strip())

        # Check channel is valid
        if channel not in required_channels:
            return {"result": "others"}

        # Check offset is one of the required values
        if offset not in required_offsets:
            return {"result": "others"}

        found_combinations.add((channel, offset))

    # Verify all 6 combinations exist (2 channels × 3 offsets)
    expected_combinations = set()
    for offset in required_offsets:
        for channel in required_channels:
            expected_combinations.add((channel, offset))

    if found_combinations != expected_combinations:
        return {"result": "others"}

    # Verify messages are customized (not all identical)
    # At least some messages should be different
    unique_messages = set(messages)
    if len(unique_messages) < 3:  # Should have at least 3 different messages
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}


######## RULE 1860 booking_scheduling_3 8
TASK: As a clinic admin, generate an invoice for booking ID 'BK-2101' using the appointment type fee, apply a 10% discount code 'NEWPATIENT10', set tax to 8%, mark the payment status as 'unpaid', and schedule an automatic payment reminder notification 3 days before the due date.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get invoice for BK-2101 from final database
    invoice_query = """
        SELECT id, booking_id, base_amount, discount_code_id, discount_amount, 
               tax_rate, tax_amount, total_amount, status, due_at
        FROM invoices 
        WHERE booking_id = ?
    """
    invoice_results = safe_query(final_db_path, invoice_query, ('BK-2101',))

    if not invoice_results:
        return {"result": "others"}

    invoice = invoice_results[0]
    invoice_id = invoice[0]
    booking_id = invoice[1]
    base_amount = invoice[2]
    discount_code_id = invoice[3]
    discount_amount = invoice[4]
    tax_rate = invoice[5]
    tax_amount = invoice[6]
    total_amount = invoice[7]
    status = invoice[8]
    due_at_str = invoice[9]

    # Verify booking_id
    if booking_id != 'BK-2101':
        return {"result": "others"}

    # Verify base_amount (should be 150.0 from appointment_types)
    if abs(base_amount - 150.0) > 0.01:
        return {"result": "others"}

    # Verify discount_code_id (1 for NEWPATIENT10)
    if discount_code_id != 1:
        return {"result": "others"}

    # Verify discount_amount (10% of 150.0 = 15.0)
    if abs(discount_amount - 15.0) > 0.01:
        return {"result": "others"}

    # Verify tax_rate (8%)
    if abs(tax_rate - 8.0) > 0.01:
        return {"result": "others"}

    # Verify tax_amount calculation: 8% of (150.0 - 15.0) = 8% of 135.0 = 10.8
    expected_tax_amount = (base_amount - discount_amount) * (tax_rate / 100.0)
    if abs(tax_amount - expected_tax_amount) > 0.01:
        return {"result": "others"}

    # Verify total_amount calculation: 150.0 - 15.0 + 10.8 = 145.8
    expected_total = base_amount - discount_amount + tax_amount
    if abs(total_amount - expected_total) > 0.01:
        return {"result": "others"}

    # Verify status is 'unpaid'
    if status != 'unpaid':
        return {"result": "others"}

    # Get invoice_notifications for this invoice
    notification_query = """
        SELECT id, invoice_id, notification_type, scheduled_at
        FROM invoice_notifications 
        WHERE invoice_id = ? AND notification_type = ?
    """
    notification_results = safe_query(final_db_path, notification_query, (invoice_id, 'payment_reminder'))

    if not notification_results:
        return {"result": "others"}

    notification = notification_results[0]
    notification_invoice_id = notification[1]
    notification_type = notification[2]
    scheduled_at_str = notification[3]

    # Verify notification_type
    if notification_type != 'payment_reminder':
        return {"result": "others"}

    # Verify notification_invoice_id matches
    if notification_invoice_id != invoice_id:
        return {"result": "others"}

    # Parse dates and verify scheduled_at is 3 days before due_at
    try:
        # Handle different datetime formats
        for fmt in ['%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d']:
            try:
                due_at = datetime.strptime(due_at_str.split('.')[0], fmt)
                break
            except ValueError:
                continue
        else:
            return {"result": "others"}

        for fmt in ['%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d']:
            try:
                scheduled_at = datetime.strptime(scheduled_at_str.split('.')[0], fmt)
                break
            except ValueError:
                continue
        else:
            return {"result": "others"}

        # Calculate expected scheduled date (3 days before due date)
        expected_scheduled = due_at - timedelta(days=3)

        # Check if scheduled_at is within same day as expected (allow time flexibility)
        if scheduled_at.date() != expected_scheduled.date():
            return {"result": "others"}

    except Exception:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}


######## RULE 2308 incident_management_1 5
TASK: Create a new integration for the service 'User Profile Service' using an Events API v2 inbound integration key, name it 'Datadog - User Profile Errors', and attach a custom incident grouping rule that groups alerts by 'source:datadog' and 'custom_field:host'.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import json
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Verify 'User Profile Service' exists
    service_query = "SELECT id FROM services WHERE name = ?"
    services = safe_query(final_db_path, service_query, ('User Profile Service',))
    if not services:
        return {"result": "others"}
    service_id = services[0][0]

    # Step 2: Check for integration with exact specifications
    integration_query = """
        SELECT id, name, type, integration_key, service_id 
        FROM integrations 
        WHERE service_id = ? AND name = ? AND type = ?
    """
    integrations = safe_query(
        final_db_path,
        integration_query,
        (service_id, 'Datadog - User Profile Errors', 'events_api_v2')
    )

    if not integrations:
        return {"result": "others"}

    integration_id = integrations[0][0]
    integration_key = integrations[0][3]

    # Verify integration has a valid key
    if not integration_key or len(integration_key.strip()) == 0:
        return {"result": "others"}

    # Step 3: Check for grouping rule with correct criteria
    grouping_rule_query = """
        SELECT id, criteria_json 
        FROM integration_grouping_rules 
        WHERE integration_id = ?
    """
    grouping_rules = safe_query(final_db_path, grouping_rule_query, (integration_id,))

    if not grouping_rules:
        return {"result": "others"}

    # Step 4: Validate the grouping rule criteria
    for rule in grouping_rules:
        criteria_json_str = rule[1]
        if not criteria_json_str:
            continue

        try:
            criteria = json.loads(criteria_json_str)
            if 'group_by' in criteria and isinstance(criteria['group_by'], list):
                group_by = criteria['group_by']
                # Check if both required grouping fields are present
                has_source_datadog = 'source:datadog' in group_by
                has_custom_field_host = 'custom_field:host' in group_by

                if has_source_datadog and has_custom_field_host:
                    # All conditions met
                    return {"result": "complete"}
        except (json.JSONDecodeError, TypeError, KeyError):
            continue

    return {"result": "others"}


######## RULE 2377 task_management_8 6
TASK: For volunteer 'Alex Martinez', self-sign them up for all open 'Kitchen Helper' shifts at the 'Downtown Shelter' between January 15 and January 31, 2026 that do not conflict with their existing assignments or stated availability.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, time

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Find Alex Martinez's volunteer_id
    alex_query = "SELECT id FROM volunteers WHERE first_name = 'Alex' AND last_name = 'Martinez'"
    alex_result = safe_query(final_db_path, alex_query)
    if not alex_result:
        return {"result": "others"}
    alex_id = alex_result[0][0]

    # Step 2: Find Kitchen Helper role_id
    role_query = "SELECT id FROM roles WHERE name = 'Kitchen Helper'"
    role_result = safe_query(final_db_path, role_query)
    if not role_result:
        return {"result": "others"}
    kitchen_helper_role_id = role_result[0][0]

    # Step 3: Find Downtown Shelter location_id (specifically Downtown Kitchen)
    location_query = "SELECT id FROM locations WHERE name IN ('Downtown Shelter', 'Downtown Kitchen') AND address LIKE '123 Main St%'"
    location_result = safe_query(final_db_path, location_query)
    if not location_result:
        return {"result": "others"}
    valid_location_ids = [row[0] for row in location_result]

    # Step 4: Find all Kitchen Helper shifts at Downtown Shelter between Jan 15-31, 2026
    target_shifts_query = """
        SELECT id, start_datetime, end_datetime, location_id
        FROM shifts
        WHERE role_id = ?
        AND location_id IN ({0})
        AND start_datetime >= '2026-01-15 00:00:00'
        AND start_datetime <= '2026-01-31 23:59:59'
        AND status = 'Open'
    """.format(','.join('?' * len(valid_location_ids)))
    target_shifts = safe_query(final_db_path, target_shifts_query, (kitchen_helper_role_id,) + tuple(valid_location_ids))

    if not target_shifts:
        return {"result": "others"}

    target_shift_ids = [shift[0] for shift in target_shifts]

    # Step 5: Get Alex's existing assignments in initial state
    initial_assignments_query = """
        SELECT sa.shift_id, s.start_datetime, s.end_datetime
        FROM shift_assignments sa
        JOIN shifts s ON sa.shift_id = s.id
        WHERE sa.volunteer_id = ?
    """
    initial_assignments = safe_query(initial_db_path, initial_assignments_query, (alex_id,))
    initial_shift_ids = {row[0] for row in initial_assignments}

    # Step 6: Get Alex's availability
    availability_query = "SELECT day_of_week, start_time, end_time FROM volunteer_availability WHERE volunteer_id = ?"
    availability = safe_query(final_db_path, availability_query, (alex_id,))

    # Create availability map
    availability_map = {}
    for day, start_str, end_str in availability:
        availability_map[day] = (start_str, end_str)

    # Step 7: Determine eligible shifts (no conflicts, matches availability)
    def parse_datetime(dt_str):
        try:
            return datetime.strptime(dt_str, '%Y-%m-%d %H:%M:%S')
        except:
            return None

    def parse_time(time_str):
        try:
            return datetime.strptime(time_str, '%H:%M:%S').time()
        except:
            return None

    def shifts_overlap(start1, end1, start2, end2):
        return start1 < end2 and start2 < end1

    def is_within_availability(shift_start, shift_end, avail_day_map):
        weekday = shift_start.weekday()
        if weekday not in avail_day_map:
            return False
        avail_start_str, avail_end_str = avail_day_map[weekday]
        avail_start = parse_time(avail_start_str)
        avail_end = parse_time(avail_end_str)
        if not avail_start or not avail_end:
            return False
        shift_start_time = shift_start.time()
        shift_end_time = shift_end.time()
        return shift_start_time >= avail_start and shift_end_time <= avail_end

    eligible_shift_ids = []
    for shift_id, start_str, end_str, loc_id in target_shifts:
        shift_start = parse_datetime(start_str)
        shift_end = parse_datetime(end_str)
        if not shift_start or not shift_end:
            continue

        # Check if already assigned in initial state
        if shift_id in initial_shift_ids:
            continue

        # Check for conflicts with existing assignments
        has_conflict = False
        for _, existing_start_str, existing_end_str in initial_assignments:
            existing_start = parse_datetime(existing_start_str)
            existing_end = parse_datetime(existing_end_str)
            if existing_start and existing_end:
                if shifts_overlap(shift_start, shift_end, existing_start, existing_end):
                    has_conflict = True
                    break

        if has_conflict:
            continue

        # Check availability
        if availability_map and not is_within_availability(shift_start, shift_end, availability_map):
            continue

        eligible_shift_ids.append(shift_id)

    # Step 8: Get final assignments for Alex
    final_assignments_query = """
        SELECT shift_id, source, status
        FROM shift_assignments
        WHERE volunteer_id = ?
    """
    final_assignments = safe_query(final_db_path, final_assignments_query, (alex_id,))
    final_shift_ids = {row[0] for row in final_assignments}

    # Step 9: Find newly created assignments
    new_assignments = []
    for shift_id, source, status in final_assignments:
        if shift_id not in initial_shift_ids and shift_id in target_shift_ids:
            new_assignments.append((shift_id, source, status))

    # Step 10: Verify all eligible shifts were assigned
    if not eligible_shift_ids:
        # No eligible shifts - task is complete if no new assignments were made
        if not new_assignments:
            return {"result": "complete"}
        return {"result": "others"}

    # Check all eligible shifts were assigned
    assigned_eligible_shifts = [sa[0] for sa in new_assignments if sa[0] in eligible_shift_ids]

    if set(assigned_eligible_shifts) != set(eligible_shift_ids):
        return {"result": "others"}

    # Step 11: Verify all new assignments are marked with source='Self'
    for shift_id, source, status in new_assignments:
        if source != 'Self':
            return {"result": "others"}

    # Step 12: Verify no ineligible shifts were assigned
    for shift_id, source, status in new_assignments:
        if shift_id not in eligible_shift_ids:
            return {"result": "others"}

    return {"result": "complete"}


