===== JSONL 6756 | professional_networking_1 | 3 =====
TASK: Create a new project in my portfolio titled 'Community Solar Grant Program 2024' with brief_description explaining that I led the proposal for a multi-state low-income community solar initiative, role_in_project set to 'Lead Grant Writer & Project Manager', start_date '2023-06-01', end_date '2024-02-15', and tags including 'grant_writing', 'community_solar', and 'stakeholder_engagement'.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get all projects from initial database
    initial_projects = safe_query(initial_db_path, "SELECT id, title, brief_description, role_in_project, start_date, end_date, owner_user_id FROM projects")
    initial_project_ids = set(p[0] for p in initial_projects)

    # Get all projects from final database
    final_projects = safe_query(final_db_path, "SELECT id, title, brief_description, role_in_project, start_date, end_date, owner_user_id FROM projects")
    final_project_ids = set(p[0] for p in final_projects)

    # Find new project IDs
    new_project_ids = final_project_ids - initial_project_ids

    # Must have exactly one new project
    if len(new_project_ids) != 1:
        return {"result": "others"}

    new_project_id = list(new_project_ids)[0]

    # Find the new project details
    new_project = None
    for p in final_projects:
        if p[0] == new_project_id:
            new_project = p
            break

    if not new_project:
        return {"result": "others"}

    project_id, title, brief_desc, role, start_date, end_date, owner_id = new_project

    # Check title exactly matches
    if title != "Community Solar Grant Program 2024":
        return {"result": "others"}

    # Check role_in_project exactly matches
    if role != "Lead Grant Writer & Project Manager":
        return {"result": "others"}

    # Check start_date
    if start_date != "2023-06-01":
        return {"result": "others"}

    # Check end_date
    if end_date != "2024-02-15":
        return {"result": "others"}

    # Check brief_description contains key concepts
    if not brief_desc:
        return {"result": "others"}

    brief_desc_lower = brief_desc.lower()
    # Must mention leading/led the proposal
    if not re.search(r"le[ad]\s+(the\s+)?proposal", brief_desc_lower):
        return {"result": "others"}

    # Must mention multi-state
    if "multi-state" not in brief_desc_lower and "multistate" not in brief_desc_lower:
        return {"result": "others"}

    # Must mention low-income or low income
    if "low-income" not in brief_desc_lower and "low income" not in brief_desc_lower:
        return {"result": "others"}

    # Must mention community solar
    if "community solar" not in brief_desc_lower:
        return {"result": "others"}

    # Check tags - get tag IDs for the required tags
    required_tag_names = ["grant_writing", "community_solar", "stakeholder_engagement"]
    tag_ids = {}
    for tag_name in required_tag_names:
        tag_result = safe_query(final_db_path, "SELECT id FROM tags WHERE name = ?", (tag_name,))
        if not tag_result:
            return {"result": "others"}
        tag_ids[tag_name] = tag_result[0][0]

    # Check project_tags table for all three tags
    project_tags = safe_query(final_db_path, "SELECT tag_id FROM project_tags WHERE project_id = ?", (new_project_id,))
    project_tag_ids = set(pt[0] for pt in project_tags)

    # Verify all three required tags are present
    for tag_name in required_tag_names:
        if tag_ids[tag_name] not in project_tag_ids:
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}
===== JSONL 9500 | booking_reservations_18 | 6 =====
TASK: Process a partial refund of 40.00 USD on the most recent successful payment made by member ID 5678 due to a class cancellation and update the corresponding invoice status accordingly.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Find the most recent successful payment for member_id=5678 in initial database
    initial_payments = safe_query(
        initial_db_path,
        "SELECT id, amount, processed_at, invoice_id FROM payments WHERE member_id = ? AND status = 'succeeded' ORDER BY processed_at DESC",
        (5678,)
    )

    if not initial_payments:
        return {"result": "others"}

    most_recent_payment_id = initial_payments[0][0]
    most_recent_invoice_id = initial_payments[0][3]

    # Step 2: Check initial refunds for this payment
    initial_refunds = safe_query(
        initial_db_path,
        "SELECT id, amount, currency FROM payment_refunds WHERE payment_id = ?",
        (most_recent_payment_id,)
    )

    # Step 3: Check final refunds for this payment
    final_refunds = safe_query(
        final_db_path,
        "SELECT id, amount, currency, reason FROM payment_refunds WHERE payment_id = ?",
        (most_recent_payment_id,)
    )

    # Step 4: Verify a new refund was added
    if len(final_refunds) <= len(initial_refunds):
        return {"result": "others"}

    # Step 5: Find the new refund(s)
    initial_refund_ids = {r[0] for r in initial_refunds}
    new_refunds = [r for r in final_refunds if r[0] not in initial_refund_ids]

    if not new_refunds:
        return {"result": "others"}

    # Step 6: Check if any new refund matches the requirements (40.00 USD)
    found_correct_refund = False
    for refund in new_refunds:
        amount = refund[1]
        currency = refund[2]
        reason = refund[3] if len(refund) > 3 else ""

        # Check amount is exactly 40.00
        if abs(amount - 40.0) < 0.01 and currency == "USD":
            # Check reason mentions class cancellation
            if reason and re.search(r"class.*cancel", reason, re.IGNORECASE):
                found_correct_refund = True
                break

    if not found_correct_refund:
        return {"result": "others"}

    # Step 7: Check invoice status was updated
    if most_recent_invoice_id:
        initial_invoice = safe_query(
            initial_db_path,
            "SELECT status, balance_due FROM invoices WHERE id = ?",
            (most_recent_invoice_id,)
        )

        final_invoice = safe_query(
            final_db_path,
            "SELECT status, balance_due FROM invoices WHERE id = ?",
            (most_recent_invoice_id,)
        )

        if not initial_invoice or not final_invoice:
            return {"result": "others"}

        initial_status = initial_invoice[0][0]
        initial_balance = initial_invoice[0][1]
        final_status = final_invoice[0][0]
        final_balance = final_invoice[0][1]

        # After a refund, the invoice should either:
        # - Have status changed from 'paid' to something else (like 'partially_refunded')
        # - Or have balance_due updated to reflect the refund
        # The initial invoice was 'paid' with balance_due=0, so after refund it should change
        if initial_status == "paid" and initial_balance == 0.0:
            # Invoice should have been updated
            if final_status == "paid" and final_balance == 0.0:
                # Invoice not updated - task incomplete
                return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

