######## RULE 2720 learning_management_system_6 4
TASK: As an instructor, enroll 25 specified learners (by their learner IDs [101,102,103,104,105,106,107,108,109,110,111,112,113,114,115,116,117,118,119,120,121,122,123,124,125]) into the course 'Introduction to Workplace Cybersecurity' with enrollment status 'invited' and a cohort-based start date of March 1, 2026 and end date of March 31, 2026.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import date

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Define the required learner IDs
    required_learner_ids = list(range(101, 126))  # [101, 102, ..., 125]

    # Get the course ID for 'Introduction to Workplace Cybersecurity'
    course_query = "SELECT id FROM courses WHERE title = ?"
    course_result = safe_query(final_db_path, course_query, ('Introduction to Workplace Cybersecurity',))

    if not course_result:
        return {"result": "others"}

    course_id = course_result[0][0]

    # Get the cohort with the specified dates for this course
    cohort_query = "SELECT id FROM cohorts WHERE course_id = ? AND start_date = ? AND end_date = ?"
    cohort_result = safe_query(final_db_path, cohort_query, (course_id, '2026-03-01', '2026-03-31'))

    if not cohort_result:
        return {"result": "others"}

    cohort_id = cohort_result[0][0]

    # Verify all 25 learners exist
    learners_query = "SELECT id FROM users WHERE id IN ({})" .format(','.join('?' * len(required_learner_ids)))
    learners_result = safe_query(final_db_path, learners_query, tuple(required_learner_ids))

    if len(learners_result) != 25:
        return {"result": "others"}

    # Check enrollments for all 25 learners
    enrollment_query = """
        SELECT user_id, course_id, cohort_id, status, start_date, end_date
        FROM enrollments
        WHERE user_id IN ({}) AND course_id = ? AND cohort_id = ?
    """.format(','.join('?' * len(required_learner_ids)))

    params = tuple(required_learner_ids) + (course_id, cohort_id)
    enrollments = safe_query(final_db_path, enrollment_query, params)

    # Should have exactly 25 enrollments
    if len(enrollments) != 25:
        return {"result": "others"}

    # Verify each enrollment has correct attributes
    enrolled_learner_ids = set()
    for enrollment in enrollments:
        user_id, enr_course_id, enr_cohort_id, status, start_date, end_date = enrollment

        # Check all required fields
        if enr_course_id != course_id:
            return {"result": "others"}

        if enr_cohort_id != cohort_id:
            return {"result": "others"}

        if status != 'invited':
            return {"result": "others"}

        if start_date != '2026-03-01':
            return {"result": "others"}

        if end_date != '2026-03-31':
            return {"result": "others"}

        enrolled_learner_ids.add(user_id)

    # Verify all 25 required learners are enrolled (no duplicates, exact match)
    if enrolled_learner_ids != set(required_learner_ids):
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}


######## RULE 2932 productivity_1 9
TASK: Search across all my bookmarks for those tagged both 'python' and 'tutorial', then create a new collection 'Python Learning Path' with an orange color and book icon, add those search results to it, and reorder them by ascending creation date within the collection.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Step 1: Find bookmarks that have BOTH 'python' AND 'tutorial' tags in initial state
    query_python_tutorial = """
        SELECT DISTINCT b.id, b.created_at
        FROM bookmarks b
        WHERE b.id IN (
            SELECT bookmark_id FROM bookmark_tags WHERE tag = 'python'
        )
        AND b.id IN (
            SELECT bookmark_id FROM bookmark_tags WHERE tag = 'tutorial'
        )
        ORDER BY b.created_at ASC
    """
    expected_bookmarks = safe_query(initial_db_path, query_python_tutorial)

    if not expected_bookmarks:
        return {"result": "others"}

    expected_bookmark_ids = [bm[0] for bm in expected_bookmarks]
    # From initial data: bookmarks 34, 35, 36 have both tags

    # Step 2: Check if collection 'Python Learning Path' exists with correct attributes
    query_collection = """
        SELECT id, name, color, icon, owner_id
        FROM collections
        WHERE name = 'Python Learning Path'
        AND owner_id = 1
    """
    collections = safe_query(final_db_path, query_collection)

    if len(collections) != 1:
        return {"result": "others"}

    collection_id, name, color, icon, owner_id = collections[0]

    # Verify collection attributes
    if color != 'orange' or icon != 'book':
        return {"result": "others"}

    # Step 3: Check if the correct bookmarks are in the collection
    query_collection_bookmarks = """
        SELECT bc.bookmark_id, bc.position, b.created_at
        FROM bookmark_collections bc
        JOIN bookmarks b ON bc.bookmark_id = b.id
        WHERE bc.collection_id = ?
        ORDER BY bc.position ASC
    """
    collection_bookmarks = safe_query(final_db_path, query_collection_bookmarks, (collection_id,))

    if len(collection_bookmarks) != len(expected_bookmark_ids):
        return {"result": "others"}

    # Step 4: Verify all expected bookmarks are present
    actual_bookmark_ids = [cb[0] for cb in collection_bookmarks]
    if set(actual_bookmark_ids) != set(expected_bookmark_ids):
        return {"result": "others"}

    # Step 5: Verify bookmarks are ordered by ascending creation date
    # The position should correspond to creation date order
    for i in range(len(collection_bookmarks)):
        if i > 0:
            prev_created_at = collection_bookmarks[i-1][2]
            curr_created_at = collection_bookmarks[i][2]
            if prev_created_at > curr_created_at:
                return {"result": "others"}

    # Step 6: Verify positions are sequential starting from 1
    expected_positions = list(range(1, len(collection_bookmarks) + 1))
    actual_positions = [cb[1] for cb in collection_bookmarks]
    if actual_positions != expected_positions:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}


######## RULE 3041 property_management_11 0
TASK: Create a new building named 'Downtown Innovation Hub' at '200 Market St, San Francisco, CA 94105' with time zone 'America/Los_Angeles' and operational hours set to Monday–Friday 08:00–20:00 and Saturday 09:00–14:00, then add two floors (Floor 5 and Floor 6) each with default metadata placeholders.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import json

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if building exists with exact name and address
    building_query = "SELECT id, name, address, time_zone FROM buildings WHERE name = ? AND address = ?"
    building_name = "Downtown Innovation Hub"
    building_address = "200 Market St, San Francisco, CA 94105"

    buildings = safe_query(final_db_path, building_query, (building_name, building_address))

    if not buildings or len(buildings) == 0:
        return {"result": "others"}

    building_id, name, address, time_zone = buildings[0]

    # Verify time zone
    if time_zone != "America/Los_Angeles":
        return {"result": "others"}

    # Verify operational hours
    hours_query = "SELECT weekday, open_time, close_time FROM building_operational_hours WHERE building_id = ? ORDER BY weekday"
    hours = safe_query(final_db_path, hours_query, (building_id,))

    if not hours:
        return {"result": "others"}

    # Expected hours: Mon(1)-Fri(4): 08:00-20:00, Sat(5): 09:00-14:00
    expected_hours = {
        1: ("08:00", "20:00"),
        2: ("08:00", "20:00"),
        3: ("08:00", "20:00"),
        4: ("08:00", "20:00"),
        5: ("09:00", "14:00")
    }

    # Check if we have at least the required weekdays
    hours_dict = {}
    for weekday, open_time, close_time in hours:
        hours_dict[weekday] = (open_time, close_time)

    # Verify Mon-Fri (weekdays 1-4 based on 0=Monday system, but checking actual values)
    # The schema uses 0-6 for weekdays, where 0=Monday
    # So Monday=0, Tuesday=1, Wednesday=2, Thursday=3, Friday=4, Saturday=5
    expected_hours_corrected = {
        0: ("08:00", "20:00"),  # Monday
        1: ("08:00", "20:00"),  # Tuesday
        2: ("08:00", "20:00"),  # Wednesday
        3: ("08:00", "20:00"),  # Thursday
        4: ("08:00", "20:00"),  # Friday
        5: ("09:00", "14:00")   # Saturday
    }

    for weekday, (expected_open, expected_close) in expected_hours_corrected.items():
        if weekday not in hours_dict:
            return {"result": "others"}
        if hours_dict[weekday] != (expected_open, expected_close):
            return {"result": "others"}

    # Verify floors
    floors_query = "SELECT floor_number, name, metadata_json FROM floors WHERE building_id = ? ORDER BY floor_number"
    floors = safe_query(final_db_path, floors_query, (building_id,))

    if not floors or len(floors) != 2:
        return {"result": "others"}

    # Check Floor 5
    floor_5_found = False
    floor_6_found = False

    for floor_number, floor_name, metadata_json in floors:
        if floor_number == 5:
            floor_5_found = True
            if floor_name != "Floor 5":
                return {"result": "others"}
            # Check metadata for default placeholder
            if not metadata_json:
                return {"result": "others"}
            try:
                metadata = json.loads(metadata_json)
                if not isinstance(metadata, dict):
                    return {"result": "others"}
                # Check if metadata contains default placeholder reference
                metadata_str = json.dumps(metadata).lower()
                if "default" not in metadata_str and "placeholder" not in metadata_str:
                    return {"result": "others"}
            except Exception:
                return {"result": "others"}

        elif floor_number == 6:
            floor_6_found = True
            if floor_name != "Floor 6":
                return {"result": "others"}
            # Check metadata for default placeholder
            if not metadata_json:
                return {"result": "others"}
            try:
                metadata = json.loads(metadata_json)
                if not isinstance(metadata, dict):
                    return {"result": "others"}
                # Check if metadata contains default placeholder reference
                metadata_str = json.dumps(metadata).lower()
                if "default" not in metadata_str and "placeholder" not in metadata_str:
                    return {"result": "others"}
            except Exception:
                return {"result": "others"}

    if not floor_5_found or not floor_6_found:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}


######## RULE 4579 e_commerce_35 5
TASK: Create a new auction_event called 'Signed Movie Memorabilia – Spring Showcase' with start_date '2025-03-01T16:00:00Z', end_date '2025-03-08T16:00:00Z', category_scope 'memorabilia', buyer_premium_percentage 17, payment_deadline_days 7, and shipping_policies metadata describing separate shipping rules for posters, props, and scripts, then assign my existing lots with IDs [901, 902, 910] to this event.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if the auction_event exists with correct attributes
    event_query = """
        SELECT id, title, start_date, end_date, category_scope, 
               buyer_premium_percentage, payment_deadline_days, shipping_policies
        FROM auction_events
        WHERE title = ?
    """

    event_title = "Signed Movie Memorabilia – Spring Showcase"
    events = safe_query(final_db_path, event_query, (event_title,))

    if not events:
        return {"result": "others"}

    # Get the event details
    event_id, title, start_date, end_date, category_scope, buyer_premium, payment_days, shipping_policies = events[0]

    # Verify all event attributes
    # Check dates - SQLite stores as '2025-03-01 16:00:00' format
    expected_start = "2025-03-01 16:00:00"
    expected_end = "2025-03-08 16:00:00"

    if start_date != expected_start:
        return {"result": "others"}

    if end_date != expected_end:
        return {"result": "others"}

    # Check category_scope
    if category_scope != "memorabilia":
        return {"result": "others"}

    # Check buyer_premium_percentage (allow for float comparison)
    if abs(buyer_premium - 17.0) > 0.01:
        return {"result": "others"}

    # Check payment_deadline_days
    if payment_days != 7:
        return {"result": "others"}

    # Check shipping_policies contains separate rules for posters, props, and scripts
    if not shipping_policies:
        return {"result": "others"}

    shipping_lower = shipping_policies.lower()
    has_poster_rules = "poster" in shipping_lower
    has_prop_rules = "prop" in shipping_lower
    has_script_rules = "script" in shipping_lower

    if not (has_poster_rules and has_prop_rules and has_script_rules):
        return {"result": "others"}

    # Verify lots 901, 902, 910 are assigned to this event
    lot_ids = [901, 902, 910]
    lots_query = "SELECT id, auction_event_id FROM lots WHERE id IN (?, ?, ?)"
    lots = safe_query(final_db_path, lots_query, tuple(lot_ids))

    if len(lots) != 3:
        return {"result": "others"}

    # Check that all three lots are assigned to the correct event
    for lot_id, auction_event_id in lots:
        if auction_event_id != event_id:
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}


######## RULE 5066 wishlist_management_5 9
TASK: Within my family account, create a shared wishlist called 'Johnson Family Gift Pool 2025' with occasion 'holiday', event_date '2025-12-24', visibility 'link_only', assign me as owner, add family member 'Chris Johnson' as editor and 'Lily Johnson' as viewer, then add two wishlist_items: 'Nintendo Switch OLED' (price_estimate 350, desired_quantity 1, priority 'high') and 'Board Game Bundle' (price_estimate 80, desired_quantity 3, priority 'medium').
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get the owner user_id (Alex Parker should be user_id=1)
    owner_check = safe_query(final_db_path, "SELECT id FROM users WHERE username = ? OR full_name = ?", ("alex_user", "Alex Parker"))
    if not owner_check:
        return {"result": "others"}
    owner_id = owner_check[0][0]

    # Check if wishlist with exact title exists in final database
    wishlist_query = """
        SELECT id, owner_id, occasion_type, event_date, visibility 
        FROM wishlists 
        WHERE title = 'Johnson Family Gift Pool 2025'
    """
    final_wishlists = safe_query(final_db_path, wishlist_query)

    if not final_wishlists:
        return {"result": "others"}

    # Verify wishlist attributes
    wishlist_found = False
    target_wishlist_id = None

    for wl in final_wishlists:
        wl_id, wl_owner_id, wl_occasion, wl_event_date, wl_visibility = wl
        if (wl_owner_id == owner_id and 
            wl_occasion == 'holiday' and 
            wl_event_date == '2025-12-24' and 
            wl_visibility == 'link_only'):
            wishlist_found = True
            target_wishlist_id = wl_id
            break

    if not wishlist_found or target_wishlist_id is None:
        return {"result": "others"}

    # Get user_ids for Chris Johnson and Lily Johnson
    chris_check = safe_query(final_db_path, "SELECT id FROM users WHERE full_name = ?", ("Chris Johnson",))
    lily_check = safe_query(final_db_path, "SELECT id FROM users WHERE full_name = ?", ("Lily Johnson",))

    if not chris_check or not lily_check:
        return {"result": "others"}

    chris_id = chris_check[0][0]
    lily_id = lily_check[0][0]

    # Verify owner collaborator exists
    owner_collab = safe_query(final_db_path, 
        "SELECT role FROM wishlist_collaborators WHERE wishlist_id = ? AND user_id = ?",
        (target_wishlist_id, owner_id))
    if not owner_collab or owner_collab[0][0] != 'owner':
        return {"result": "others"}

    # Verify Chris Johnson as editor
    chris_collab = safe_query(final_db_path, 
        "SELECT role FROM wishlist_collaborators WHERE wishlist_id = ? AND user_id = ?",
        (target_wishlist_id, chris_id))
    if not chris_collab or chris_collab[0][0] != 'editor':
        return {"result": "others"}

    # Verify Lily Johnson as viewer
    lily_collab = safe_query(final_db_path, 
        "SELECT role FROM wishlist_collaborators WHERE wishlist_id = ? AND user_id = ?",
        (target_wishlist_id, lily_id))
    if not lily_collab or lily_collab[0][0] != 'viewer':
        return {"result": "others"}

    # Verify Nintendo Switch OLED item
    switch_item = safe_query(final_db_path, """
        SELECT price_estimate, desired_quantity, priority 
        FROM wishlist_items 
        WHERE wishlist_id = ? AND name = 'Nintendo Switch OLED'
    """, (target_wishlist_id,))

