                            (leg_ids[0], leg_ids[1], crew_201_id, crew_202_id, crew_330_id))

    # We should have 6 assignments total (3 crew x 2 legs)
    if len(assignments) < 6:
        return {"result": "others"}

    # Group assignments by flight_leg and crew
    leg_crew_assignments = {}
    for flight_leg_id, crew_id, role, duty_start, duty_end in assignments:
        if flight_leg_id not in leg_crew_assignments:
            leg_crew_assignments[flight_leg_id] = {}
        leg_crew_assignments[flight_leg_id][crew_id] = {
            'role': role,
            'duty_start': duty_start,
            'duty_end': duty_end
        }

    # Verify each leg has all three crew members assigned
    for leg_id in leg_ids:
        if leg_id not in leg_crew_assignments:
            return {"result": "others"}
        if len(leg_crew_assignments[leg_id]) != 3:
            return {"result": "others"}

        # Check all three crew members are present
        assigned_crew_ids = set(leg_crew_assignments[leg_id].keys())
        if assigned_crew_ids != {crew_201_id, crew_202_id, crew_330_id}:
            return {"result": "others"}

        # Verify roles are appropriate
        c201_role = leg_crew_assignments[leg_id][crew_201_id]['role']
        c202_role = leg_crew_assignments[leg_id][crew_202_id]['role']
        c330_role = leg_crew_assignments[leg_id][crew_330_id]['role']

        # C-201 and C-202 should be pilot roles
        if c201_role not in ['pilot_in_command', 'second_in_command']:
            return {"result": "others"}
        if c202_role not in ['pilot_in_command', 'second_in_command']:
            return {"result": "others"}
        # C-330 should be flight_attendant
        if c330_role != 'flight_attendant':
            return {"result": "others"}

    # Verify duty time calculations
    # Get all crew_assignments for these crew members to check 24-hour duty limits
    all_assignments_query = """SELECT crew_id, duty_start_time, duty_end_time 
                               FROM crew_assignments 
                               WHERE crew_id IN (?, ?, ?)
                               ORDER BY crew_id, duty_start_time"""
    all_assignments = safe_query(final_db_path, all_assignments_query,
                                 (crew_201_id, crew_202_id, crew_330_id))

    # Check duty time limits for each crew member
    def parse_datetime(dt_str):
        try:
            return datetime.strptime(dt_str, '%Y-%m-%d %H:%M:%S')
        except:
            return None

    def check_duty_hours(assignments_list):
        for i, (crew_id, start, end) in enumerate(assignments_list):
            start_dt = parse_datetime(start)
            end_dt = parse_datetime(end)
            if not start_dt or not end_dt:
                continue

            # Calculate duration in hours
            duration = (end_dt - start_dt).total_seconds() / 3600
            if duration > 10:
                return False

            # Check overlapping 24-hour windows with other assignments
            for j, (other_crew_id, other_start, other_end) in enumerate(assignments_list):
                if i == j or crew_id != other_crew_id:
                    continue

                other_start_dt = parse_datetime(other_start)
                other_end_dt = parse_datetime(other_end)
                if not other_start_dt or not other_end_dt:
                    continue

                # Check if within 24 hours
                time_diff = abs((other_start_dt - start_dt).total_seconds() / 3600)
                if time_diff < 24:
                    # Calculate total duty time in any 24-hour period
                    window_start = min(start_dt, other_start_dt)
                    window_end = window_start + timedelta(hours=24)

                    total_duty = 0
                    for _, check_start, check_end in assignments_list:
                        if _ != crew_id:
                            continue
                        check_start_dt = parse_datetime(check_start)
                        check_end_dt = parse_datetime(check_end)
                        if not check_start_dt or not check_end_dt:
                            continue

                        # Check overlap with 24-hour window
                        overlap_start = max(window_start, check_start_dt)
                        overlap_end = min(window_end, check_end_dt)
                        if overlap_start < overlap_end:
                            overlap_hours = (overlap_end - overlap_start).total_seconds() / 3600
                            total_duty += overlap_hours

                    if total_duty > 10:
                        return False
        return True

    duty_valid = check_duty_hours(all_assignments)

    # Check final_answer for indication of success or violations
    if not final_answer:
        return {"result": "others"}

    final_answer_lower = final_answer.lower()

    # Look for key indicators in the answer
    has_assignment_info = bool(re.search(r'(crew.*assign|assign.*crew|c-201|c-202|c-330)', final_answer_lower))
    has_leg_info = bool(re.search(r'(fl-7752|fl-8003|flight.*leg)', final_answer_lower))

    # The task should return information about violations or successful assignment
    if has_assignment_info and has_leg_info:
        return {"result": "complete"}

    return {"result": "others"}

