RULE 2478 professional_networking_7 9
TASK: Generate a list of recommended opportunities for me based on my current profile skills and location, filter out remote roles, keep only full-time positions with seniority 'Senior' or 'Lead', and automatically apply to the top two recommendations by compensation using my default profile without adding any custom notes.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get initial applications for user_id=1
    initial_apps = safe_query(initial_db_path, "SELECT id, opportunity_id FROM applications WHERE user_id = 1")
    initial_app_ids = set([app[0] for app in initial_apps])
    initial_opp_ids = set([app[1] for app in initial_apps])

    # Get final applications for user_id=1
    final_apps = safe_query(final_db_path, "SELECT id, opportunity_id, status, applicant_note FROM applications WHERE user_id = 1")
    final_app_ids = set([app[0] for app in final_apps])

    # Find new applications
    new_app_ids = final_app_ids - initial_app_ids

    # Check if exactly 2 new applications were created
    if len(new_app_ids) != 2:
        return {"result": "others"}

    # Get details of new applications
    new_apps = [app for app in final_apps if app[0] in new_app_ids]

    # Verify all new applications have status 'applied' and no custom notes
    for app in new_apps:
        app_id, opp_id, status, note = app
        if status != 'applied':
            return {"result": "others"}
        # Check that applicant_note is NULL or empty (default profile, no custom notes)
        if note is not None and note.strip() != '':
            return {"result": "others"}

    # Get the opportunity IDs that were applied to
    new_opp_ids = [app[1] for app in new_apps]

    # Get user's skills (user_id=1)
    user_skills = safe_query(final_db_path, "SELECT skill_id FROM user_skills WHERE user_id = 1")
    user_skill_ids = set([skill[0] for skill in user_skills])

    # Get user's location
    user_info = safe_query(final_db_path, "SELECT location FROM users WHERE id = 1")
    if not user_info:
        return {"result": "others"}
    user_location = user_info[0][0] if user_info[0][0] else ""

    # Get all eligible opportunities (non-remote, full-time, Senior or Lead, published)
    eligible_opps_query = """
        SELECT id, seniority, role_type, is_remote, compensation_max, compensation_min, location
        FROM opportunities
        WHERE is_remote = 0
        AND role_type = 'full-time'
        AND (seniority = 'Senior' OR seniority = 'Lead')
        AND is_published = 1
    """
    eligible_opps = safe_query(final_db_path, eligible_opps_query)

    if not eligible_opps:
        return {"result": "others"}

    # Filter opportunities that match user's skills and location
    matching_opps = []
    for opp in eligible_opps:
        opp_id, seniority, role_type, is_remote, comp_max, comp_min, location = opp

        # Get opportunity skills
        opp_skills = safe_query(final_db_path, "SELECT skill_id FROM opportunity_skills WHERE opportunity_id = ?", (opp_id,))
        opp_skill_ids = set([skill[0] for skill in opp_skills])

        # Check if user has at least one matching skill
        if not user_skill_ids.intersection(opp_skill_ids):
            continue

        matching_opps.append({
            'id': opp_id,
            'compensation_max': comp_max if comp_max is not None else 0,
            'seniority': seniority,
            'role_type': role_type,
            'is_remote': is_remote
        })

    if len(matching_opps) < 2:
        return {"result": "others"}

    # Sort by compensation_max descending to get top 2
    matching_opps.sort(key=lambda x: x['compensation_max'], reverse=True)
    top_2_opp_ids = [opp['id'] for opp in matching_opps[:2]]

    # Verify that the new applications are for the top 2 opportunities
    if set(new_opp_ids) != set(top_2_opp_ids):
        return {"result": "others"}

    # Verify each applied opportunity meets all criteria
    for opp_id in new_opp_ids:
        opp_details = safe_query(final_db_path, 
            "SELECT is_remote, role_type, seniority FROM opportunities WHERE id = ?", 
            (opp_id,))

        if not opp_details:
            return {"result": "others"}

        is_remote, role_type, seniority = opp_details[0]

        # Verify non-remote
        if is_remote != 0:
            return {"result": "others"}

        # Verify full-time
        if role_type != 'full-time':
            return {"result": "others"}

        # Verify Senior or Lead
        if seniority not in ['Senior', 'Lead']:
            return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

RULE 1315 survey_feedback_platform_1 8
TASK: Update the existing 'Outpatient Surgical Experience' survey by inserting a mandatory multiple-choice question after question 5 that asks 'Did you understand the post-operative care instructions?' with options 'Yes, completely', 'Somewhat', 'Not at all', and ensure all future invitations use the updated survey version while preserving prior response data.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # 1. Verify the 'Outpatient Surgical Experience' survey exists (id=3)
    survey_check = safe_query(final_db_path, "SELECT id, name FROM surveys WHERE name = ?", ('Outpatient Surgical Experience',))
    if not survey_check or survey_check[0][0] != 3:
        return {"result": "others"}
    survey_id = survey_check[0][0]

    # 2. Check initial state - survey should have had 2 versions (version 1 and 2)
    initial_versions = safe_query(initial_db_path, "SELECT id, version_number, is_active FROM survey_versions WHERE survey_id = ? ORDER BY version_number", (survey_id,))
    if len(initial_versions) != 2:
        return {"result": "others"}

    # 3. Check final state - survey should now have 3 versions
    final_versions = safe_query(final_db_path, "SELECT id, version_number, is_active FROM survey_versions WHERE survey_id = ? ORDER BY version_number", (survey_id,))
    if len(final_versions) != 3:
        return {"result": "others"}

    # 4. The new version should be version 3 and should be active
    new_version = [v for v in final_versions if v[1] == 3]
    if not new_version or new_version[0][2] != 1:
        return {"result": "others"}
    new_version_id = new_version[0][0]

    # 5. The previous active version (version 2) should now be inactive or the new one is active
    version_2 = [v for v in final_versions if v[1] == 2]
    if not version_2:
        return {"result": "others"}

    # 6. Get all questions for the new version
    new_version_questions = safe_query(final_db_path, 
        "SELECT id, text, question_type, is_required, display_order FROM survey_questions WHERE survey_version_id = ? ORDER BY display_order",
        (new_version_id,))

    if len(new_version_questions) < 4:
        return {"result": "others"}

    # 7. Find the post-operative care instructions question
    postop_question = None
    for q in new_version_questions:
        q_id, q_text, q_type, q_required, q_order = q
        # Check if this is the post-operative care question
        if 'post-operative care instructions' in q_text.lower() or 'postop' in q_text.lower():
            if 'understand' in q_text.lower():
                postop_question = q
                break

    if not postop_question:
        return {"result": "others"}

    postop_q_id, postop_text, postop_type, postop_required, postop_order = postop_question

    # 8. Verify the question is mandatory and multiple_choice
    if postop_type != 'multiple_choice' or postop_required != 1:
        return {"result": "others"}

    # 9. Verify the question is inserted after question at position 5 or earlier questions
    # The question should be at position 3, 4, 5, or 6 based on the structure
    # Since version 2 had questions at positions 1,2,3,4, the new question should be somewhere in between
    if postop_order < 1 or postop_order > 10:
        return {"result": "others"}

    # 10. Get the options for this question
    options = safe_query(final_db_path,
        "SELECT option_label FROM survey_question_options WHERE survey_question_id = ? ORDER BY display_order",
        (postop_q_id,))

    if len(options) != 3:
        return {"result": "others"}

    # 11. Verify the exact three options exist
    option_labels = [opt[0] for opt in options]
    required_options = ['Yes, completely', 'Somewhat', 'Not at all']

    # Check if all required options are present (case-insensitive and flexible matching)
    found_options = set()
    for opt_label in option_labels:
        opt_lower = opt_label.lower().strip()
        if 'yes' in opt_lower and 'completely' in opt_lower:
            found_options.add('yes_completely')
        elif opt_lower == 'somewhat':
            found_options.add('somewhat')
        elif 'not' in opt_lower and 'at all' in opt_lower:
            found_options.add('not_at_all')

    if len(found_options) != 3:
        return {"result": "others"}

    # 12. Verify prior response data is preserved
    initial_responses = safe_query(initial_db_path, "SELECT COUNT(*) FROM survey_responses")
    final_responses = safe_query(final_db_path, "SELECT COUNT(*) FROM survey_responses")

    if not initial_responses or not final_responses:
        return {"result": "others"}

    if initial_responses[0][0] != final_responses[0][0]:
        return {"result": "others"}

    # 13. Verify prior invitations are preserved
    initial_invitations = safe_query(initial_db_path, "SELECT COUNT(*) FROM survey_invitations")
    final_invitations = safe_query(final_db_path, "SELECT COUNT(*) FROM survey_invitations")

    if not initial_invitations or not final_invitations:
        return {"result": "others"}

    if initial_invitations[0][0] > final_invitations[0][0]:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

RULE 1750 e_commerce_marketplace_12 6
TASK: Get a list of all my active listings that have been in my closet for more than 90 days without a sale and apply a 20% price reduction to each of those listings.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    from datetime import datetime, timedelta

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Calculate the date threshold (90 days ago from 2025-12-31 12:38:07)
    # Based on the database timestamps, current time appears to be around 2025-12-31
    reference_date = '2025-12-31 12:38:07'
    try:
        ref_dt = datetime.strptime(reference_date, '%Y-%m-%d %H:%M:%S')
        threshold_date = ref_dt - timedelta(days=90)
        threshold_str = threshold_date.strftime('%Y-%m-%d %H:%M:%S')
    except Exception:
        return {"result": "others"}

    # Get active listings from main_seller (user_id=1) in initial state
    initial_query = """
        SELECT id, listing_price_cents, closet_created_at
        FROM listings
        WHERE seller_id = 1 AND status = 'active'
    """
    initial_listings = safe_query(initial_db_path, initial_query)

    if not initial_listings:
        return {"result": "others"}

    # Get all orders to identify listings that have been sold
    orders_query = "SELECT DISTINCT listing_id FROM orders"
    sold_listing_ids = set(row[0] for row in safe_query(initial_db_path, orders_query))

    # Identify listings that qualify for price reduction
    # Criteria: active, closet_created_at > 90 days ago, never sold
    qualifying_listings = []
    for listing_id, price_cents, closet_created_at in initial_listings:
        # Skip if listing has been sold
        if listing_id in sold_listing_ids:
            continue

        # Check if closet_created_at is more than 90 days ago
        try:
            if closet_created_at and closet_created_at < threshold_str:
                qualifying_listings.append((listing_id, price_cents))
        except Exception:
            continue

    # If no qualifying listings, the task might still be complete (empty result)
    # But based on the data, there should be qualifying listings (e.g., listing 9, 10, 11, 14, 15)
    if len(qualifying_listings) == 0:
        return {"result": "others"}

    # Get final state of all listings from seller_id=1
    final_query = """
        SELECT id, listing_price_cents
        FROM listings
        WHERE seller_id = 1
    """
    final_listings = safe_query(final_db_path, final_query)

    if not final_listings:
        return {"result": "others"}

    # Create a map of final prices
    final_prices = {listing_id: price for listing_id, price in final_listings}

    # Verify that all qualifying listings have 20% price reduction
    all_reduced_correctly = True
    for listing_id, initial_price in qualifying_listings:
        if listing_id not in final_prices:
            return {"result": "others"}

        final_price = final_prices[listing_id]
        expected_price = int(initial_price * 0.8)

        # Allow for minor rounding differences (within 1 cent)
        if abs(final_price - expected_price) > 1:
            all_reduced_correctly = False
            break

    if not all_reduced_correctly:
        return {"result": "others"}

    # Verify that non-qualifying listings from seller_id=1 remain unchanged
    initial_prices_map = {listing_id: price for listing_id, price, _ in initial_listings}

    for listing_id, initial_price, _ in initial_listings:
        # Skip qualifying listings (already checked)
        if any(ql[0] == listing_id for ql in qualifying_listings):
            continue

        if listing_id in final_prices:
            # Non-qualifying listings should have unchanged prices
            if final_prices[listing_id] != initial_price:
                return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

