        reason = refund[3] if len(refund) > 3 else ""

        # Check amount is exactly 40.00
        if abs(amount - 40.0) < 0.01 and currency == "USD":
            # Check reason mentions class cancellation
            if reason and re.search(r"class.*cancel", reason, re.IGNORECASE):
                found_correct_refund = True
                break

