TASK: Using my linked student_id and current meal_plan_balance, purchase the 'Silver Weekday Lunch' meal_plan for the 'Main Campus' campus and return my updated meal_plan_balance and wallet_balance.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get initial state
    initial_wallet = safe_query(initial_db_path, "SELECT wallet_balance FROM user_wallets WHERE user_id = ?", (1,))
    if not initial_wallet:
        return {"result": "others"}
    initial_wallet_balance = initial_wallet[0][0]

    # Get meal plan info
    meal_plan_info = safe_query(initial_db_path, "SELECT id, price FROM meal_plans WHERE name = ? AND campus_id = (SELECT id FROM campuses WHERE name = ?)", ('Silver Weekday Lunch', 'Main Campus'))
    if not meal_plan_info:
        return {"result": "others"}
    meal_plan_id, meal_plan_price = meal_plan_info[0]

    # Get initial user_meal_plans count for this specific meal plan
    initial_meal_plans = safe_query(initial_db_path, "SELECT id FROM user_meal_plans WHERE user_id = ? AND meal_plan_id = ? AND campus_id = ?", (1, meal_plan_id, 1))
    initial_count = len(initial_meal_plans)

    # Get final state
    final_wallet = safe_query(final_db_path, "SELECT wallet_balance FROM user_wallets WHERE user_id = ?", (1,))
    if not final_wallet:
        return {"result": "others"}
    final_wallet_balance = final_wallet[0][0]

    # Get final user_meal_plans for this specific meal plan
    final_meal_plans = safe_query(final_db_path, "SELECT id, purchase_price, balance_value, active FROM user_meal_plans WHERE user_id = ? AND meal_plan_id = ? AND campus_id = ?", (1, meal_plan_id, 1))
    final_count = len(final_meal_plans)

    # Check 1: A new meal plan record was added
    if final_count <= initial_count:
        return {"result": "others"}

    # Check 2: Wallet was debited by meal plan price
    expected_wallet_balance = round(initial_wallet_balance - meal_plan_price, 2)
    if abs(final_wallet_balance - expected_wallet_balance) > 0.01:
        return {"result": "others"}

    # Check 3: Find the new meal plan record (should be the one not in initial)
    initial_ids = set(record[0] for record in initial_meal_plans)
    new_records = [record for record in final_meal_plans if record[0] not in initial_ids]

    if not new_records:
        return {"result": "others"}

    # Check 4: Verify the new record has correct values
    new_record = new_records[0]
    purchase_price = new_record[1]
    balance_value = new_record[2]
    active = new_record[3]

    if abs(purchase_price - meal_plan_price) > 0.01:
        return {"result": "others"}

    if abs(balance_value - meal_plan_price) > 0.01:
        return {"result": "others"}

    if active != 1:
        return {"result": "others"}

    # Check 5: Verify final_answer contains both balances
    if not final_answer:
        return {"result": "others"}

    # Extract balances from final_answer using flexible patterns
    meal_plan_balance_pattern = r'meal[_\s-]*plan[_\s-]*balance[^\d]*(\d+(?:\.\d+)?)'
    wallet_balance_pattern = r'wallet[_\s-]*balance[^\d]*(\d+(?:\.\d+)?)'

    meal_plan_match = re.search(meal_plan_balance_pattern, final_answer, re.IGNORECASE)
    wallet_match = re.search(wallet_balance_pattern, final_answer, re.IGNORECASE)

    if not meal_plan_match or not wallet_match:
        return {"result": "others"}

    try:
        returned_meal_plan_balance = float(meal_plan_match.group(1))
        returned_wallet_balance = float(wallet_match.group(1))
    except (ValueError, AttributeError):
        return {"result": "others"}

    # Check 6: Verify returned balances match database
    if abs(returned_meal_plan_balance - balance_value) > 0.01:
        return {"result": "others"}

    if abs(returned_wallet_balance - final_wallet_balance) > 0.01:
        return {"result": "others"}

    return {"result": "complete"}

