TASK: For an existing charter_request with ID CR-1042, generate quotes from all eligible operators, then return the cheapest quote that still falls within its validity_period and includes a detailed pricing_breakdown.
def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import re
    import json
    from datetime import datetime

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Get charter request details
    cr_query = "SELECT id, origin_airport_id, destination_airport_id, passenger_count, luggage_volume_cuft FROM charter_requests WHERE request_code = 'CR-1042'"
    cr_results = safe_query(final_db_path, cr_query)
    if not cr_results:
        return {"result": "others"}

    cr_id, origin_id, dest_id, passenger_count, luggage_volume = cr_results[0]

    # Get eligible operators based on operator_eligibility_rules
    # Route is KJFK (id=3) to KBUR (id=4), 4 passengers, 20 cuft luggage
    eligible_ops_query = """
        SELECT DISTINCT operator_id 
        FROM operator_eligibility_rules 
        WHERE allowed_origin_airport_id = ? 
        AND allowed_destination_airport_id = ?
        AND (min_passengers IS NULL OR min_passengers <= ?)
        AND (max_passengers IS NULL OR max_passengers >= ?)
        AND (max_luggage_volume_cuft IS NULL OR max_luggage_volume_cuft >= ?)
    """
    eligible_ops = safe_query(final_db_path, eligible_ops_query, 
                             (origin_id, dest_id, passenger_count, passenger_count, luggage_volume))

    if not eligible_ops:
        return {"result": "others"}

    eligible_operator_ids = set(op[0] for op in eligible_ops)

    # Expected operators: 1, 2, 3 based on the initial data
    expected_operators = {1, 2, 3}
    if not expected_operators.issubset(eligible_operator_ids):
        return {"result": "others"}

    # Get quotes for CR-1042 from final database
    quotes_query = """
        SELECT id, quote_code, operator_id, total_price, validity_start, validity_end, 
               pricing_breakdown, status
        FROM quotes 
        WHERE charter_request_id = ?
    """
    final_quotes = safe_query(final_db_path, quotes_query, (cr_id,))

    if not final_quotes:
        return {"result": "others"}

    # Get quotes from initial database to identify new ones
    initial_quotes = safe_query(initial_db_path, quotes_query, (cr_id,))
    initial_quote_ids = set(q[0] for q in initial_quotes)

    # Filter for new quotes
    new_quotes = [q for q in final_quotes if q[0] not in initial_quote_ids]

    # Check if quotes exist from all eligible operators
    all_quote_operators = set(q[2] for q in final_quotes)
    if not expected_operators.issubset(all_quote_operators):
        return {"result": "others"}

    # Find valid quotes with pricing_breakdown
    valid_quotes = []
    current_time = datetime.now()

    for quote in final_quotes:
        quote_id, quote_code, operator_id, total_price, validity_start, validity_end, pricing_breakdown, status = quote

        # Check if pricing_breakdown exists and is not empty
        if not pricing_breakdown or pricing_breakdown.strip() == '':
            continue

        # Try to parse pricing_breakdown as JSON to ensure it's detailed
        try:
            breakdown = json.loads(pricing_breakdown)
            if not isinstance(breakdown, dict) or len(breakdown) == 0:
                continue
        except (json.JSONDecodeError, TypeError):
            continue

        # Check validity period
        try:
            validity_start_dt = datetime.strptime(validity_start, '%Y-%m-%d %H:%M:%S')
            validity_end_dt = datetime.strptime(validity_end, '%Y-%m-%d %H:%M:%S')

            # Quote should be valid (either currently or in reasonable future)
            if validity_end_dt < validity_start_dt:
                continue

        except (ValueError, TypeError):
            continue

        valid_quotes.append({
            'id': quote_id,
            'code': quote_code,
            'operator_id': operator_id,
            'price': total_price,
            'breakdown': pricing_breakdown,
            'validity_start': validity_start,
            'validity_end': validity_end
        })

    if not valid_quotes:
        return {"result": "others"}

    # Find the cheapest quote
    cheapest_quote = min(valid_quotes, key=lambda q: q['price'])

    # Verify final_answer contains the cheapest quote information
    if not final_answer:
        return {"result": "others"}

    # Check if final_answer mentions the quote code
    quote_code_pattern = re.escape(cheapest_quote['code'])
    if not re.search(quote_code_pattern, final_answer, re.IGNORECASE):
        return {"result": "others"}

    # Check if final_answer mentions the price
    price_str = str(cheapest_quote['price'])
    if not re.search(re.escape(price_str), final_answer):
        return {"result": "others"}

    # Check if final_answer contains pricing breakdown information
    try:
        breakdown = json.loads(cheapest_quote['breakdown'])
        # Check for at least 3 breakdown components mentioned
        breakdown_count = 0
        for key, value in breakdown.items():
            if re.search(re.escape(str(value)), final_answer) or re.search(re.escape(key), final_answer, re.IGNORECASE):
                breakdown_count += 1

        if breakdown_count < 3:
            return {"result": "others"}
    except (json.JSONDecodeError, TypeError):
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

