import json
import os
import sys
from pathlib import Path

SOURCE = Path('/workspace/data/AgentWorldModel-1K/gen_verifier.pure_code.jsonl')
OUTPUT = Path(sys.argv[1]) if len(sys.argv) > 1 else SOURCE
rows = [json.loads(line) for line in SOURCE.open()]
changes = []


def edit(idx, old, new, note):
    code = rows[idx]['verification']['code']
    count = code.count(old)
    if count != 1:
        raise RuntimeError(f'rule {idx}: expected one match, got {count}: {old[:100]!r}')
    rows[idx]['verification']['code'] = code.replace(old, new, 1)
    changes.append((idx, rows[idx]['scenario'], rows[idx]['task_idx'], note))


