import json
import shutil
import sqlite3
from datetime import datetime, timedelta
from pathlib import Path

ROOT = Path('/tmp/awm-analysis-FY8vek')
DBDIR = ROOT / 'initial_dbs'
OUT = ROOT / 'positive_dbs'
OUT.mkdir(exist_ok=True)
RULES = [json.loads(line) for line in (ROOT / 'gen_verifier.pure_code.patched.jsonl').open()]


def clone_row(conn, table, row_id, updates=None):
    updates = dict(updates or {})
    columns = [row[1] for row in conn.execute(f'PRAGMA table_info({table})')]
    row = conn.execute(f'SELECT * FROM {table} WHERE id = ?', (row_id,)).fetchone()
    if row is None:
        raise AssertionError(f'missing {table} id {row_id}')
    values = dict(zip(columns, row))
    new_id = updates.pop('id', None)
    if new_id is None:
        new_id = conn.execute(f'SELECT COALESCE(MAX(id), 0) + 1 FROM {table}').fetchone()[0]
    values['id'] = new_id
    values.update(updates)
    conn.execute(f'INSERT INTO {table} ({",".join(columns)}) VALUES ({",".join("?" for _ in columns)})',
                 tuple(values[column] for column in columns))
    return new_id


def clone_children(conn, table, parent_column, old_parent_id, new_parent_id, updates=None):
    columns = [row[1] for row in conn.execute(f'PRAGMA table_info({table})')]
    rows = conn.execute(f'SELECT * FROM {table} WHERE {parent_column} = ?', (old_parent_id,)).fetchall()
    result = []
    for row in rows:
        values = dict(zip(columns, row))
        if 'id' in columns:
            values['id'] = conn.execute(f'SELECT COALESCE(MAX(id), 0) + 1 FROM {table}').fetchone()[0]
        values[parent_column] = new_parent_id
        values.update(updates or {})
        conn.execute(f'INSERT INTO {table} ({",".join(columns)}) VALUES ({",".join("?" for _ in columns)})',
                     tuple(values[column] for column in columns))
        result.append(values.get('id'))
    return result


def scalar(conn, query, params=()):
    row = conn.execute(query, params).fetchone()
    assert row is not None, (query, params)
    return row[0]


def delete_target_initial(idx, conn):
    if idx == 1860:
        conn.execute("DELETE FROM invoices WHERE booking_id = 'BK-2101'")
    elif idx == 609:
        conn.execute("DELETE FROM event_type_reminders WHERE event_type_id = (SELECT id FROM event_types WHERE name = 'Webinar Q&A')")
    elif idx == 3041:
        conn.execute("DELETE FROM buildings WHERE name = 'Downtown Innovation Hub'")
    elif idx == 4579:
        conn.execute("DELETE FROM auction_events WHERE title = 'Signed Movie Memorabilia – Spring Showcase'")
    elif idx == 9515:
        conn.execute("DELETE FROM segments WHERE name = 'Lapsed Major Donors'")
    elif idx == 9301:
        conn.execute("DELETE FROM watchlists WHERE user_id = 1 AND name = 'Tech Giants'")
        conn.execute("DELETE FROM price_alerts WHERE user_id = 1 AND asset_id = (SELECT id FROM assets WHERE symbol = 'AAPL' AND asset_type = 'stock') AND direction = 'below' AND threshold_price = 180.0 AND is_active = 1")
    elif idx == 2720:
        conn.execute("DELETE FROM enrollments WHERE user_id BETWEEN 101 AND 125 AND course_id = 1 AND cohort_id = 1")
    elif idx == 8055:
        conn.execute("DELETE FROM vehicles WHERE vin_metadata = '19XFC2F59KE000123'")
        conn.execute("DELETE FROM customers WHERE full_name = 'Jordan Smith' AND phone = '555-910-2233' AND email = 'jordan.smith@example.com'")
    elif idx == 5173:
        conn.execute("DELETE FROM documents WHERE title = 'API Design Template v2'")
    elif idx == 6133:
        conn.execute("DELETE FROM opportunity_listings WHERE title = 'Summer 2026 Marketing Internship' AND id != 2875")
    elif idx == 7643:
        conn.execute("DELETE FROM form_templates WHERE organization_id = 1 AND name = 'New Patient Intake - Adult'")
    elif idx == 5066:
        conn.execute("DELETE FROM wishlists WHERE title = 'Johnson Family Gift Pool 2025'")
    elif idx == 2932:
        conn.execute("DELETE FROM collections WHERE name = 'Python Learning Path' AND owner_id = 1")
    elif idx == 8335:
        conn.execute("DELETE FROM tariffs WHERE utility_id = 7 AND name = 'Residential-Water-2025'")
    elif idx == 2308:
        conn.execute("DELETE FROM integrations WHERE name = 'Datadog - User Profile Errors' AND type = 'events_api_v2'")
    elif idx == 118:
        conn.execute("UPDATE tasks SET status = 'pending' WHERE id = 2")
    elif idx == 7478:
        conn.execute("UPDATE appointments SET scheduled_start = '2025-01-13 09:00:00', status = 'confirmed', metadata = '{}' WHERE id = 'APT-98342'")
    elif idx == 9519:
        conn.execute("DELETE FROM volunteer_skills WHERE user_id = 1 AND skill_id = 3")
    elif idx == 7157:
        conn.execute("UPDATE event_rsvps SET roles_pref = NULL, locations_pref = NULL WHERE event_id = 301 AND student_profile_id = (SELECT id FROM student_profiles WHERE user_id = 1)")
    elif idx == 7309:
        conn.execute("DELETE FROM progress_reports WHERE application_id = 310 AND milestone_id = (SELECT id FROM milestones WHERE application_id = 310 AND name = 'Phase 1 site preparation completed')")
    elif idx == 5953:
        conn.execute("DELETE FROM crew_assignments WHERE flight_leg_id IN (SELECT id FROM flight_legs WHERE booking_id = (SELECT id FROM bookings WHERE booking_code = 'BK-4309')) AND crew_id IN (SELECT id FROM crew WHERE crew_code IN ('C-201', 'C-202', 'C-330'))")
    else:
        raise AssertionError(f'no deletion case for {idx}')


def make_pair(idx, scenario):
    initial = OUT / f'{idx}_initial.db'
    final = OUT / f'{idx}_final.db'
    for path in (initial, final):
        if path.exists():
            path.unlink()
        shutil.copyfile(DBDIR / f'{scenario}.db', path)
    return initial, final


def build_custom_final(idx, initial, final):
    init = sqlite3.connect(initial)
    conn = sqlite3.connect(final)
    if idx == 5410:
        source = scalar(conn, "SELECT id FROM patients WHERE full_name = 'Maria Gonzalez' AND date_of_birth = '1985-07-14'")
        clone_row(conn, 'patients', source)
    elif idx == 6243:
        source = scalar(conn, "SELECT id FROM bookings WHERE owner_id = 1 AND service_type = 'overnight' AND zip_code = '10001' ORDER BY id LIMIT 1")
        new_id = clone_row(conn, 'bookings', source, {'sitter_id': 452, 'service_type': 'overnight', 'status': 'requested', 'start_time': '2025-07-03 19:00:00', 'end_time': '2025-07-04 08:00:00', 'zip_code': '10001', 'special_notes': 'Needs medication at 10pm and 7am'})
        clone_children(conn, 'booking_pets', 'booking_id', source, new_id)
        # Ensure Buddy is linked even if the source booking used another pet.
        columns = [row[1] for row in conn.execute('PRAGMA table_info(booking_pets)')]
        if 'pet_id' in columns:
            conn.execute('DELETE FROM booking_pets WHERE booking_id = ?', (new_id,))
            pet_values = {'booking_id': new_id, 'pet_id': 1}
            if 'id' in columns:
                pet_values['id'] = scalar(conn, 'SELECT COALESCE(MAX(id), 0) + 1 FROM booking_pets')
            for column in columns:
                pet_values.setdefault(column, None)
            conn.execute(f'INSERT INTO booking_pets ({",".join(columns)}) VALUES ({",".join("?" for _ in columns)})', tuple(pet_values[c] for c in columns))
        clone_children(conn, 'booking_status_history', 'booking_id', source, new_id, {'new_status': 'requested'})
    elif idx == 900:
        source = scalar(conn, "SELECT id FROM service_listings WHERE title = '30-Minute Neighborhood Dog Walks' ORDER BY id LIMIT 1")
        new_id = clone_row(conn, 'service_listings', source, {'sitter_id': 1})
        clone_children(conn, 'service_listing_zipcodes', 'service_listing_id', source, new_id)
    elif idx == 7178:
        source = scalar(conn, "SELECT id FROM leave_requests WHERE employee_id = 209 AND time_off_type = 'vacation' AND start_date = '2025-06-10' AND end_date = '2025-06-14' ORDER BY id LIMIT 1")
        clone_row(conn, 'leave_requests', source, {'approval_status': 'approved', 'total_hours': 40.0, 'reason': 'Family trip'})
        conn.execute("UPDATE leave_accruals SET accrual_balance_hours = accrual_balance_hours - 40.0 WHERE employee_id = 209 AND time_off_type = 'vacation'")
    elif idx == 5737:
        meal_plan_id = scalar(conn, "SELECT id FROM meal_plans WHERE name = 'Silver Weekday Lunch' AND campus_id = (SELECT id FROM campuses WHERE name = 'Main Campus')")
        source = scalar(conn, 'SELECT id FROM user_meal_plans WHERE user_id = 1 AND meal_plan_id = ? AND campus_id = 1 ORDER BY id LIMIT 1', (meal_plan_id,))
        clone_row(conn, 'user_meal_plans', source, {'purchase_price': 120.0, 'balance_value': 120.0, 'active': 1})
    elif idx == 8894:
        source = scalar(conn, 'SELECT id FROM board_section_resources WHERE board_id = 1 AND board_section_id = 1 AND resource_id = 1 AND added_by_user_id = 1 ORDER BY id LIMIT 1')
        clone_row(conn, 'board_section_resources', source)
    elif idx == 1750:
        threshold = (datetime.now() - timedelta(days=90)).strftime('%Y-%m-%d %H:%M:%S')
        sold = {row[0] for row in conn.execute('SELECT DISTINCT listing_id FROM orders')}
        rows = conn.execute("SELECT id, listing_price_cents, closet_created_at FROM listings WHERE seller_id = 1 AND status = 'active'").fetchall()
        qualifying = [(row[0], row[1]) for row in rows if row[0] not in sold and row[2] and row[2] < threshold]
        assert qualifying
        for listing_id, price in qualifying:
            conn.execute('UPDATE listings SET listing_price_cents = ? WHERE id = ?', (int(price * 0.8), listing_id))
    elif idx == 4452:
        source_watch = scalar(conn, 'SELECT id FROM watchlists WHERE lot_id = 5501 ORDER BY id LIMIT 1')
        clone_row(conn, 'watchlists', source_watch, {'user_id': 1})
        source_bid = scalar(conn, 'SELECT id FROM lot_bids WHERE lot_id = 5501 ORDER BY id LIMIT 1')
        clone_row(conn, 'lot_bids', source_bid, {'bidder_id': 1, 'bid_amount': 260.0, 'auto_bid_max': 400.0})
        conn.execute('UPDATE lot_bid_stats SET highest_bid_amount = 260.0, number_of_bids = number_of_bids + 1 WHERE lot_id = 5501')
    elif idx == 2862:
        source = scalar(conn, "SELECT id FROM fare_products WHERE name = 'Weekend Saver' ORDER BY id LIMIT 1")
        new_id = clone_row(conn, 'fare_products', source)
        clone_children(conn, 'route_fare_products', 'fare_product_id', source, new_id)
    elif idx == 2478:
