def clone_row(conn, table, row_id, updates=None):
    updates = dict(updates or {})
    columns = [row[1] for row in conn.execute(f'PRAGMA table_info({table})')]
    row = conn.execute(f'SELECT * FROM {table} WHERE id = ?', (row_id,)).fetchone()
    if row is None:
        raise AssertionError(f'missing {table} id {row_id}')
    values = dict(zip(columns, row))
    new_id = updates.pop('id', None)
    if new_id is None:
        new_id = conn.execute(f'SELECT COALESCE(MAX(id), 0) + 1 FROM {table}').fetchone()[0]
    values['id'] = new_id
    values.update(updates)
    conn.execute(f'INSERT INTO {table} ({",".join(columns)}) VALUES ({",".join("?" for _ in columns)})',
                 tuple(values[column] for column in columns))
    return new_id


def clone_children(conn, table, parent_column, old_parent_id, new_parent_id, updates=None):
    columns = [row[1] for row in conn.execute(f'PRAGMA table_info({table})')]
    rows = conn.execute(f'SELECT * FROM {table} WHERE {parent_column} = ?', (old_parent_id,)).fetchall()
    result = []
    for row in rows:
        values = dict(zip(columns, row))
        if 'id' in columns:
            values['id'] = conn.execute(f'SELECT COALESCE(MAX(id), 0) + 1 FROM {table}').fetchone()[0]
        values[parent_column] = new_parent_id
        values.update(updates or {})
        conn.execute(f'INSERT INTO {table} ({",".join(columns)}) VALUES ({",".join("?" for _ in columns)})',
                     tuple(values[column] for column in columns))
        result.append(values.get('id'))
    return result


