python -I -W ignore::SyntaxWarning - <<'PY'
import hashlib,json
from collections import Counter
from pathlib import Path
import pyarrow.parquet as pq
root=Path('/workspace/data/AgentWorldModel-1K')
orig_path=root/'gen_verifier.pure_code.jsonl'
new_path=Path('/tmp/awm-analysis-FY8vek/gen_verifier.pure_code.patched.jsonl')
orig_bytes=orig_path.read_bytes(); new_bytes=new_path.read_bytes()
orig_lines=orig_bytes.splitlines(keepends=True); new_lines=new_bytes.splitlines(keepends=True)
orig=[json.loads(x) for x in orig_lines]; new=[json.loads(x) for x in new_lines]
assert len(orig)==len(new)==10010
changed=[]
for i,(a,b) in enumerate(zip(orig,new)):
 assert a.keys()==b.keys(), i
 for key in a:
  if key=='verification':
   assert a[key].keys()==b[key].keys(), i
   for subkey in a[key]:
    if subkey!='code': assert a[key][subkey]==b[key][subkey], (i,key,subkey)
  else: assert a[key]==b[key], (i,key)
 if a!=b:
  changed.append(i)
  assert a['scenario']==b['scenario'] and a['task_idx']==b['task_idx']
  assert a['verification']['code']!=b['verification']['code']
 else: assert orig_lines[i]==new_lines[i], i
keys=lambda rows: Counter((r['scenario'],r['task_idx']) for r in rows)
assert keys(orig)==keys(new)
assert len(keys(new))==10000
test=pq.read_table(root/'verl/test.parquet').to_pylist()
heldout={(r['env_kwargs']['scenario'],r['env_kwargs']['task_idx']) for r in test}
assert len(heldout)==128 and heldout<=set(keys(new))
lookup={}
for i,r in enumerate(new): lookup.setdefault((r['scenario'],r['task_idx']),i)
selected=[lookup[key] for key in heldout]
for i in selected: compile(new[i]['verification']['code'],f'<selected-{i}>','exec')
def syntax_errors(rows):
 errors={}
 for i,r in enumerate(rows):
  try: compile(r['verification']['code'],f'<rule-{i}>','exec')
  except SyntaxError as e: errors[i]=str(e)
 return errors
orig_errors=syntax_errors(orig); new_errors=syntax_errors(new)
assert orig_errors==new_errors
assert not set(new_errors)&heldout
print('original_sha256',hashlib.sha256(orig_bytes).hexdigest())
print('candidate_sha256',hashlib.sha256(new_bytes).hexdigest())
print('records',len(new),'unique_task_keys',len(keys(new)),'heldout_keys',len(heldout))
print('changed_records',len(changed),changed)
print('unrelated_lines_byte_identical',len(new)-len(changed))
print('selected_rules_compiled',len(selected))
print('unchanged_preexisting_nonheldout_syntax_errors',new_errors)
